-- Mural de Saúde, termo 2026-10-25 (roda uma vez só; rodar o arquivo de novo não repete): todos os perfis ficam
-- esperando o novo aceite, a nova assinatura e a nova aprovação do texto (pela regra do termo vigente, saem do ar
-- sozinhos), e cada profissional recebe o aviso no painel. Quem é de categoria ainda fechada recebe o aviso próprio.
do $$
declare s record;
begin
  if coalesce((select (valor ->> 'termo_2026_10_25')::boolean from interno.configuracoes where chave = 'saude_migracoes'), false) then return; end if;
  for s in select usuario, conselho from interno.saude_perfis where status <> 'removido' and termo_versao is distinct from interno.saude_termo_vigente() loop
    update interno.saude_perfis set texto_aprovado_em = null where usuario = s.usuario;
    perform interno.avisar(s.usuario, case when interno.saude_categoria_ligada(s.conselho)
      then 'O termo do Mural de Saúde mudou (versão ' || interno.saude_termo_vigente() || ') para seguir as normas de publicidade do seu conselho. O seu cartão saiu do ar até você ler o aviso, aceitar o novo termo, assinar no gov.br e aprovar o texto de novo no painel.'
      else 'O Mural de Saúde está aberto, por enquanto, só para a psicologia. O seu perfil continua guardado, mas saiu do ar até as normas de publicidade do seu conselho serem revisadas.' end);
    perform interno.saude_registrar(s.usuario, 'aguardando_novo_aceite', jsonb_build_object('versao', interno.saude_termo_vigente()));
  end loop;
  insert into interno.configuracoes (chave, valor) values ('saude_migracoes', jsonb_build_object('termo_2026_10_25', true))
  on conflict (chave) do update set valor = interno.configuracoes.valor || jsonb_build_object('termo_2026_10_25', true);
end $$;
-- As duas regras do depósito "saude" são lidas pelas políticas do Storage com o papel de quem envia: ficam só para authenticated.
revoke all on function interno.saude_deposita() from public, anon;
revoke all on function interno.saude_le_tudo() from public, anon;
revoke all on function interno.saude_gere() from public, anon;
do $$
declare f text;
begin
  foreach f in array array['disciplina_convidar(uuid, text, text, text)', 'disciplina_convites()', 'disciplina_convite_revogar(uuid)',
    'traducao_convidar(text, text, uuid)', 'traducao_coautor_tirar(text, text, uuid)', 'fotos_pendentes()', 'foto_decidir(uuid, boolean)',
    'termo_registrar(text, text, text, jsonb)', 'termos_meus()', 'termos_aceites_listar(uuid)',
    'saude_meu()', 'saude_salvar(jsonb)', 'saude_termo_aceitar(text, text, text, boolean, boolean)', 'saude_aviso_ciente()', 'saude_sair()', 'saude_fila()', 'saude_decidir(uuid, text, date, text)',
    'saude_chave(boolean)', 'saude_vitrine()', 'erro_relatar(jsonb)', 'erros_listar()', 'erro_mudar(uuid, text, text)',
    'saude_editar(uuid, jsonb)', 'saude_aprovar_texto()', 'saude_assinatura_enviar(text, text)', 'saude_assinatura_conferir(uuid, boolean, text)',
    'saude_verificacao_anexar(uuid, text, text, text)', 'saude_registro_listar(uuid)'] loop
    execute format('revoke all on function public.%s from public', f);
    execute format('grant execute on function public.%s to anon, authenticated, service_role', f);
  end loop;
end $$;

-- Funções internas usadas só por dentro de outras funções: ninguém de fora as executa (o esquema já é fechado; isto é a
-- segunda tranca).
revoke all on function interno.curriculo_decide() from public, anon, authenticated;
revoke all on function interno.curriculo_json(interno.curriculo_propostas) from public, anon, authenticated;
revoke all on function interno.reuniao_entra(interno.reunioes) from public, anon, authenticated;
revoke all on function interno.reuniao_json(interno.reunioes) from public, anon, authenticated;
revoke all on function interno.revisa_caderno(text) from public, anon, authenticated;
revoke all on function interno.caderno_pronto_json(interno.cadernos_prontos) from public, anon, authenticated;
revoke all on function interno.resolve_questoes() from public, anon, authenticated;

-- ───────────────────────────── Atividade do site ─────────────────────────────
-- Tudo o que a galera posta (envios de conteúdo, o que vai ao ar, Comunidade, anotações, Mural dos Trabalhadores, Gaveta
-- Aberta, reforço, aulas em vídeo e ao vivo, podcast, artes do estúdio e o Mural da equipe) vira uma linha aqui, para a
-- coordenação acompanhar. Do Mural da equipe só entra que houve publicação e em qual canal: o texto é cifrado e fica lá.
-- Cada pessoa da coordenação escolhe como quer saber: só no painel, um e-mail a cada postagem ou um resumo por dia.
create table if not exists interno.atividade (
  id uuid primary key default gen_random_uuid(),
  tipo text not null check (tipo ~ '^[a-z_]{3,30}$'),
  titulo text not null default '' check (char_length(titulo) <= 200),
  resumo text not null default '' check (char_length(resumo) <= 400),
  link text not null default '' check (char_length(link) <= 300),
  autor uuid references interno.perfis (id) on delete set null,
  autor_nome text not null default '' check (char_length(autor_nome) <= 120),
  publico boolean not null default true,
  criado_em timestamptz not null default now()
);
create index if not exists atividade_recente on interno.atividade (criado_em desc);
create index if not exists atividade_tipo on interno.atividade (tipo, criado_em desc);

create table if not exists interno.atividade_assinaturas (
  usuario uuid primary key references interno.perfis (id) on delete cascade,
  modo text not null default 'painel' check (modo in ('painel', 'cada', 'resumo')),
  -- Os tipos que vão por e-mail (vazio: todos). No painel aparece tudo, com filtro.
  tipos text[] not null default '{}',
  visto_em timestamptz not null default now(),
  resumo_em timestamptz
);
alter table interno.atividade enable row level security;
alter table interno.atividade_assinaturas enable row level security;

/** Quem acompanha a atividade do site: coordenação e coordenação pedagógica. */
-- Quem acompanha a Atividade do site: a coordenação, a coordenação pedagógica, a supervisão, a revisão e a mediação.
create or replace function interno.acompanha() returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select interno.coord() or interno.tem('vice') or interno.tem('supervisao') or interno.tem('revisao') or interno.tem('mediacao')
$$;

/**
 * Registra uma postagem e manda o e-mail para quem assina "a cada postagem". Nunca impede ninguém de postar: qualquer
 * falha aqui é engolida (no pior caso, a linha não aparece).
 */
create or replace function interno.atividade_nova(p_tipo text, p_titulo text, p_resumo text, p_link text, p_autor uuid, p_publico boolean) returns void language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_nome text; r record; v_link text;
begin
  v_nome := coalesce((select nome from perfis where id = p_autor), '');
  v_link := left(coalesce(p_link, ''), 300);
  insert into atividade (tipo, titulo, resumo, link, autor, autor_nome, publico)
  values (p_tipo, left(coalesce(p_titulo, ''), 200), left(regexp_replace(coalesce(p_resumo, ''), '\s+', ' ', 'g'), 400), v_link, p_autor, left(v_nome, 120), coalesce(p_publico, true));
  for r in select distinct u.email from atividade_assinaturas s
             join papeis p on p.usuario = s.usuario and p.papel in ('coordenacao', 'vice')
             join auth.users u on u.id = s.usuario join perfis f on f.id = s.usuario
           where s.modo = 'cada' and not f.suspenso and coalesce(u.email, '') <> '' and s.usuario is distinct from p_autor
             and (cardinality(s.tipos) = 0 or p_tipo = any (s.tipos)) loop
    perform interno.email(r.email, 'atividade', left('Novo no site: ' || coalesce(p_titulo, ''), 200),
      coalesce(p_titulo, '') || case when v_nome <> '' then E'\nPor ' || interno.primeiro_nome(v_nome) else '' end
        || case when coalesce(p_resumo, '') <> '' then E'\n\n' || left(p_resumo, 300) else '' end
        || E'\n\n' || interno.endereco() || '/pt' || case when v_link like '/%' then v_link else '/painel?aba=atividade' end
        || E'\n\nPara mudar estes avisos: painel, Atividade do site, Como me avisar.',
      '', 80);
  end loop;
  if random() < 0.01 then delete from atividade where criado_em < now() - interval '180 days'; end if;
exception when others then null;
end $$;

create or replace function interno.atividade_rotulo(p_tipo text) returns text language sql immutable as $$
  select case p_tipo when 'aula' then 'Aula' when 'obra' then 'Obra para o acervo' when 'artigo' then 'Matéria para o jornal' when 'checagem' then 'Checagem'
    when 'debate' then 'Resposta para debate' when 'verbete' then 'Verbete' when 'memorial' then 'Nome para o Memorial' when 'video' then 'Vídeo indicado'
    when 'frase' then 'Frase' when 'traducao' then 'Tradução' when 'correcao' then 'Correção' when 'sugestao' then 'Sugestão' when 'questao' then 'Questão'
    when 'avulso' then 'Material avulso' when 'temas' then 'Próximas aulas' when 'pratica' then 'Prática de idioma' else initcap(coalesce(p_tipo, 'Envio')) end
$$;

create or replace function interno.atividade_gatilho() returns trigger language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  case tg_table_name
    when 'contribuicoes' then
      if tg_op = 'INSERT' then
        perform interno.atividade_nova('envio', interno.atividade_rotulo(new.tipo) || ': ' || new.titulo, coalesce(new.disciplina, ''),
          case when new.como = 'publico' then '/painel?aba=triagem' else '/painel?aba=fila' end, new.autor, new.como = 'publico');
      elsif new.status = 'publicada' and old.status is distinct from 'publicada' then
        perform interno.atividade_nova('no_ar', 'No ar: ' || new.titulo, interno.atividade_rotulo(new.tipo), '/painel?aba=fila', new.autor, new.como = 'publico');
      end if;
    when 'topicos' then
      perform interno.atividade_nova('comunidade', 'Pergunta na Comunidade: ' || new.titulo, left(new.corpo, 300), '/comunidade?t=' || new.id, new.autor, true);
    when 'respostas' then
      perform interno.atividade_nova('comunidade', 'Resposta na Comunidade: ' || coalesce((select titulo from topicos where id = new.topico), ''), left(new.corpo, 300), '/comunidade?t=' || new.topico, new.autor, true);
    when 'anotacoes' then
      perform interno.atividade_nova('anotacao', 'Anotação numa aula', left(new.corpo, 300), new.caminho, new.autor, true);
    when 'mural' then
      perform interno.atividade_nova('mural', 'Mural dos Trabalhadores: ' || new.titulo, new.cidade || coalesce(' · ' || nullif(new.uf, ''), ''), '/painel?aba=mural', new.autor, true);
    when 'gaveta' then
      perform interno.atividade_nova('gaveta', 'Gaveta Aberta: ' || new.titulo, new.tipo || ' · ' || new.disciplina, '/painel?aba=gaveta', new.autor, true);
    when 'reforco' then
      perform interno.atividade_nova('reforco', 'Pedido de reforço: ' || new.assunto, new.disciplina, '/painel?aba=reforco', new.autor, true);
    when 'videoaulas' then
      perform interno.atividade_nova('video', 'Aula em vídeo: ' || new.titulo, new.disciplina, '/painel?aba=videoaulas', new.autor, false);
    when 'aulas_ao_vivo' then
      perform interno.atividade_nova('aovivo', 'Aula ao vivo marcada: ' || new.titulo, to_char(new.inicio at time zone 'America/Sao_Paulo', 'DD/MM HH24:MI') || ' · ' || new.disciplina, '/painel?aba=aovivo', new.educador, false);
    when 'podcast_episodios' then
      perform interno.atividade_nova('podcast', 'Episódio de podcast: ' || new.titulo, left(new.resumo, 300), '/painel?aba=podcast', new.criado_por, false);
    when 'designs' then
      perform interno.atividade_nova('arte', 'Arte no estúdio: ' || new.titulo, new.formato, '/painel?aba=estudio', new.autor, false);
    when 'equipe_mensagens' then
      perform interno.atividade_nova('equipe', case when new.resposta_a is null then 'Publicação no Mural da equipe' else 'Resposta no Mural da equipe' end, 'canal ' || new.canal, '/painel?aba=rede', new.autor, false);
    else null;
  end case;
  return new;
exception when others then
  return new;
end $$;

do $$
declare t text;
begin
  foreach t in array array['contribuicoes', 'topicos', 'respostas', 'anotacoes', 'mural', 'gaveta', 'reforco', 'videoaulas', 'aulas_ao_vivo', 'podcast_episodios', 'designs', 'equipe_mensagens'] loop
    if to_regclass('interno.' || t) is not null then
      execute format('drop trigger if exists atividade on interno.%I', t);
      if t = 'contribuicoes' then
        execute 'create trigger atividade after insert or update of status on interno.contribuicoes for each row execute function interno.atividade_gatilho()';
      else
        execute format('create trigger atividade after insert on interno.%I for each row execute function interno.atividade_gatilho()', t);
      end if;
    end if;
  end loop;
end $$;

create or replace function interno.atividade_json(a interno.atividade) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select jsonb_build_object('id', a.id, 'tipo', a.tipo, 'titulo', a.titulo, 'resumo', a.resumo, 'link', a.link, 'autor', interno.nome_visto(nullif(a.autor_nome, '')),
    'publico', a.publico, 'criado_em', a.criado_em, 'minha', a.autor = auth.uid())
$$;

/** A linha do tempo (60 por vez, das mais novas para trás), com o que eu já vi e como quero ser avisado. */
create or replace function public.atividade_listar(p_antes timestamptz default null, p_tipo text default null) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); s atividade_assinaturas;
begin
  if not interno.acompanha() then perform interno.erro('sem_permissao'); end if;
  select * into s from atividade_assinaturas where usuario = v;
  return jsonb_build_object(
    'itens', (select coalesce(jsonb_agg(interno.atividade_json(a) order by a.criado_em desc), '[]'::jsonb)
              from (select * from atividade where (p_antes is null or criado_em < p_antes) and (p_tipo is null or tipo = p_tipo) order by criado_em desc limit 60) a),
    'visto_em', coalesce(s.visto_em, now() - interval '7 days'),
    'modo', coalesce(s.modo, 'painel'),
    'tipos', to_jsonb(coalesce(s.tipos, '{}'::text[])),
    'contagem', (select coalesce(jsonb_object_agg(tipo, n), '{}'::jsonb) from (select tipo, count(*) as n from atividade where criado_em > now() - interval '7 days' group by tipo) c));
end $$;

/** Para o menu e os avisos do navegador: quantas postagens eu não vi e a mais nova. Quem não acompanha recebe zero. */
create or replace function public.atividade_resumo() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := auth.uid(); v_desde timestamptz;
begin
  if v is null or not interno.acompanha() then return jsonb_build_object('nao_vistas', 0); end if;
  v_desde := coalesce((select visto_em from atividade_assinaturas where usuario = v), now() - interval '7 days');
  return jsonb_build_object(
    'nao_vistas', (select count(*) from atividade where criado_em > v_desde and autor is distinct from v),
    'ultima', (select interno.atividade_json(a) from atividade a where autor is distinct from v order by criado_em desc limit 1));
end $$;

create or replace function public.atividade_visto() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not interno.acompanha() then perform interno.erro('sem_permissao'); end if;
  insert into atividade_assinaturas (usuario, visto_em) values (v, now()) on conflict (usuario) do update set visto_em = now();
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.atividade_assinar(p_modo text, p_tipos text[] default '{}') returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_tipos text[];
begin
  if not interno.acompanha() then perform interno.erro('sem_permissao'); end if;
  if coalesce(p_modo, '') not in ('painel', 'cada', 'resumo') then perform interno.erro('invalido:modo'); end if;
  v_tipos := array(select distinct x from unnest(coalesce(p_tipos, '{}'::text[])) x
                   where x in ('envio', 'no_ar', 'comunidade', 'anotacao', 'mural', 'gaveta', 'reforco', 'video', 'aovivo', 'podcast', 'arte', 'equipe'));
  insert into atividade_assinaturas (usuario, modo, tipos) values (v, p_modo, v_tipos)
  on conflict (usuario) do update set modo = excluded.modo, tipos = excluded.tipos;
  perform interno.registrar('atividade_assinar', p_modo, jsonb_build_object('tipos', v_tipos));
  return jsonb_build_object('modo', p_modo, 'tipos', to_jsonb(v_tipos));
end $$;

/**
 * O resumo do dia, às 20h (horário de Brasília), para quem escolheu "um resumo por dia": quantas postagens de cada tipo
 * e as mais recentes. Roda de hora em hora pelo agendador do banco; cada pessoa recebe no máximo um por dia.
 */
create or replace function interno.atividade_resumos() returns void language plpgsql security definer set search_path = interno, pg_temp as $$
declare r record; v_desde timestamptz; v_texto text; v_total integer;
begin
  if extract(hour from now() at time zone 'America/Sao_Paulo') < 20 then return; end if;
  for r in select s.usuario, s.resumo_em, s.tipos, u.email from atividade_assinaturas s
             join auth.users u on u.id = s.usuario join perfis f on f.id = s.usuario
           where s.modo = 'resumo' and not f.suspenso and coalesce(u.email, '') <> ''
             and exists (select 1 from papeis p where p.usuario = s.usuario and p.papel in ('coordenacao', 'vice'))
             and (s.resumo_em is null or (s.resumo_em at time zone 'America/Sao_Paulo')::date < (now() at time zone 'America/Sao_Paulo')::date) loop
    v_desde := coalesce(r.resumo_em, now() - interval '1 day');
    select count(*) into v_total from atividade where criado_em > v_desde and (cardinality(r.tipos) = 0 or tipo = any (r.tipos));
    update atividade_assinaturas set resumo_em = now() where usuario = r.usuario;
    if v_total = 0 then continue; end if;
    select string_agg(to_char(criado_em at time zone 'America/Sao_Paulo', 'HH24:MI') || ' · ' || titulo, E'\n' order by criado_em desc) into v_texto
      from (select criado_em, titulo from atividade where criado_em > v_desde and (cardinality(r.tipos) = 0 or tipo = any (r.tipos)) order by criado_em desc limit 25) x;
    perform interno.email(r.email, 'atividade_resumo', v_total || ' postagem(ns) no site hoje',
      'O que a galera postou desde o último resumo:' || E'\n\n' || v_texto || case when v_total > 25 then E'\n… e mais ' || (v_total - 25) || '.' else '' end
        || E'\n\n' || interno.endereco() || '/pt/painel?aba=atividade', '', 3);
  end loop;
end $$;

do $$
declare f record;
begin
  for f in select p.oid::regprocedure as assinatura, n.nspname from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where p.prokind = 'f' and n.nspname in ('public', 'interno') and (p.proname like 'atividade%' or p.proname = 'acompanha') loop
    execute format('revoke all on function %s from public', f.assinatura);
    if f.nspname = 'public' then
      execute format('grant execute on function %s to anon, authenticated, service_role', f.assinatura);
    elsif exists (select 1 from pg_roles where rolname = 'anon') then
      execute format('revoke all on function %s from anon, authenticated', f.assinatura);
    end if;
  end loop;
end $$;

do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('lucia-atividade-resumo', '7 * * * *', 'select interno.atividade_resumos()');
  end if;
exception when others then null;
end $$;

-- ───────────────────────────── Contagens anônimas ─────────────────────────────
-- Para saber se uma aula funciona e o que se lê no jornal sem vigiar ninguém: cada linha é só um total por dia
-- (tipo, alvo, dia). Nada de conta, cookie, endereço de rede ou identificador. O freio contra quem insiste em inflar
-- um número usa o mesmo limite do resto do banco, que guarda a origem embaralhada por dois dias e depois esquece.

create table if not exists interno.contagens (
  tipo text not null check (tipo in ('jornal_leu', 'aula_abriu', 'aula_terminou', 'aula_teste', 'aula_acertou', 'aula_ajudou', 'aula_nao_ajudou', 'episodio_ouviu')),
  alvo text not null check (alvo ~ '^[a-z0-9/_-]{1,160}$'),
  dia date not null default (now() at time zone 'America/Sao_Paulo')::date,
  total integer not null default 0,
  primary key (tipo, alvo, dia)
);

/** Soma um à contagem do dia. Responde sempre vazio: quem chama não fica sabendo de nada. */
create or replace function public.contar(p_tipo text, p_alvo text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  if p_tipo not in ('jornal_leu', 'aula_abriu', 'aula_terminou', 'aula_teste', 'aula_acertou', 'aula_ajudou', 'aula_nao_ajudou', 'episodio_ouviu') then return '{}'::jsonb; end if;
  if coalesce(p_alvo, '') !~ '^[a-z0-9/_-]{1,160}$' then return '{}'::jsonb; end if;
  begin
    perform interno.limite('contar:' || p_tipo || ':' || p_alvo, 3, 60);
    perform interno.limite('contar', 120, 60);
  exception when others then
    return '{}'::jsonb;
  end;
  insert into contagens (tipo, alvo, total) values (p_tipo, p_alvo, 1)
  on conflict (tipo, alvo, dia) do update set total = contagens.total + 1;
  return '{}'::jsonb;
end $$;

/** As matérias mais lidas nos últimos sete dias (só os totais, públicos por natureza). */
create or replace function public.jornal_mais_lidas() returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select coalesce(jsonb_agg(jsonb_build_object('slug', alvo, 'total', soma) order by soma desc), '[]'::jsonb)
  from (select alvo, sum(total) as soma from contagens where tipo = 'jornal_leu' and dia > (now() at time zone 'America/Sao_Paulo')::date - 7
        group by alvo order by sum(total) desc limit 5) x
$$;

/**
 * Para a equipe melhorar as aulas: por aula, quantos abriram, terminaram, fizeram e acertaram o teste e disseram que
 * ajudou ou não, nos últimos noventa dias. Só para quem escreve, revisa ou coordena.
 */
create or replace function public.aulas_funcionam(p_dias integer default 90) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  if not (interno.coord() or interno.tem('supervisao') or interno.tem('educacao') or interno.tem('revisao') or interno.tem('curadoria')) then
    perform interno.erro('sem_permissao');
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object('aula', alvo, 'abriu', abriu, 'terminou', terminou, 'teste', teste, 'acertou', acertou, 'ajudou', ajudou, 'nao_ajudou', nao_ajudou) order by abriu desc)
    from (
      select alvo,
        coalesce(sum(total) filter (where tipo = 'aula_abriu'), 0) as abriu,
        coalesce(sum(total) filter (where tipo = 'aula_terminou'), 0) as terminou,
        coalesce(sum(total) filter (where tipo = 'aula_teste'), 0) as teste,
        coalesce(sum(total) filter (where tipo = 'aula_acertou'), 0) as acertou,
        coalesce(sum(total) filter (where tipo = 'aula_ajudou'), 0) as ajudou,
        coalesce(sum(total) filter (where tipo = 'aula_nao_ajudou'), 0) as nao_ajudou
      from contagens where tipo like 'aula_%' and dia > (now() at time zone 'America/Sao_Paulo')::date - least(greatest(coalesce(p_dias, 90), 1), 365)
      group by alvo
    ) x
  ), '[]'::jsonb);
end $$;

do $$
declare f record;
begin
  for f in select p.oid::regprocedure as assinatura from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where p.prokind = 'f' and n.nspname = 'public' and p.proname in ('contar', 'jornal_mais_lidas', 'aulas_funcionam') loop
    execute format('revoke all on function %s from public', f.assinatura);
    execute format('grant execute on function %s to anon, authenticated, service_role', f.assinatura);
  end loop;
end $$;

-- Os totais diários de mais de dois anos viram um só por mês? Não: simplesmente saem, a pergunta é sempre sobre agora.
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('lucia-contagens-faxina', '41 4 * * 0', $c$delete from interno.contagens where dia < now() - interval '2 years'$c$);
  end if;
exception when others then null;
end $$;

-- ───────────────────────────── Codinomes ─────────────────────────────
-- Quem nunca trocou o "Estudante 12345" do começo ganha um codinome legível (uma vez só: o nome novo não casa mais com a
-- regra, então rodar de novo não muda nada). Nome que a pessoa escolheu nunca é tocado.
do $$
declare r record;
begin
  for r in select id from interno.perfis where nome ~ '^Estudante [0-9]{5}$' loop
    update interno.perfis set nome = interno.codinome(null) where id = r.id;
  end loop;
end $$;

-- ───────────────────────────── Bloqueio de entrada por tentativas ─────────────────────────────
-- Quem erra a senha (ou o código do autenticador) muitas vezes fica 15 minutos sem poder tentar de novo. A conta é por
-- origem embaralhada (interno.origem: o endereço de rede vira um resumo e nunca é guardado em claro) e pelo par
-- origem + conta: 5 erros na mesma conta, ou 10 em contas diferentes, a partir do mesmo lugar, em 15 minutos. Ninguém
-- consegue trancar a conta de outra pessoa de outro lugar (o bloqueio é sempre de quem tenta). A tentativa certa limpa
-- os erros do par, e só quem acabou de entrar com aquela conta consegue limpar.

create table if not exists interno.entradas_falhas (
  origem text not null,
  conta text not null,
  quando timestamptz not null default now()
);
create index if not exists entradas_falhas_origem on interno.entradas_falhas (origem, quando);

create or replace function interno.entrada_situacao_json(p_conta text) returns jsonb
language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare
  v_origem text := interno.origem();
  v_desde timestamptz := now() - interval '15 minutes';
  v_par integer;
  v_todas integer;
  v_primeira timestamptz;
begin
  select count(*) into v_par from entradas_falhas where origem = v_origem and conta = p_conta and quando > v_desde;
  select count(*), min(quando) into v_todas, v_primeira from entradas_falhas where origem = v_origem and quando > v_desde;
  if v_par >= 5 or v_todas >= 10 then
    return jsonb_build_object('bloqueado', true, 'segundos', greatest(60, ceil(extract(epoch from (
      (select min(quando) from entradas_falhas where origem = v_origem and quando > v_desde and (v_todas >= 10 or conta = p_conta)) + interval '15 minutes' - now())))::integer));
  end if;
  return jsonb_build_object('bloqueado', false, 'restam', least(5 - v_par, 10 - v_todas));
end $$;

/** Antes de tentar: a origem está bloqueada para esta conta? (O e-mail vira um resumo, nunca é guardado.) */
create or replace function public.entrada_situacao(p_email text) returns jsonb
language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  perform interno.limite('entrada_situacao', 60, 15);
  return interno.entrada_situacao_json(md5('conta:' || lower(btrim(coalesce(p_email, '')))));
end $$;

/** Depois de um erro de senha ou de código: anota e devolve a situação. */
create or replace function public.entrada_falhou(p_email text) returns jsonb
language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_conta text := md5('conta:' || lower(btrim(coalesce(p_email, ''))));
begin
  perform interno.limite('entrada_falhou', 40, 15);
  insert into entradas_falhas (origem, conta) values (interno.origem(), v_conta);
  if random() < 0.05 then delete from entradas_falhas where quando < now() - interval '1 day'; end if;
  return interno.entrada_situacao_json(v_conta);
end $$;

/** Entrou: limpa os erros do par. Só vale para quem está com a sessão daquela conta aberta. */
create or replace function public.entrada_certa() returns jsonb
language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_email text := lower(coalesce((select email from auth.users where id = auth.uid()), ''));
begin
  if auth.uid() is null or v_email = '' then return jsonb_build_object('ok', false); end if;
  delete from entradas_falhas where origem = interno.origem() and conta = md5('conta:' || v_email);
  return jsonb_build_object('ok', true);
end $$;

do $$
declare f record;
begin
  for f in select p.oid::regprocedure as assinatura from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where p.prokind = 'f' and n.nspname = 'public' and p.proname in ('entrada_situacao', 'entrada_falhou', 'entrada_certa') loop
    execute format('revoke all on function %s from public', f.assinatura);
    execute format('grant execute on function %s to anon, authenticated, service_role', f.assinatura);
  end loop;
end $$;
revoke all on function interno.entrada_situacao_json(text) from public;

-- ───────────────────────────── Cuidado com a equipe ─────────────────────────────
-- Cinco ideias do painel:
--   1. agradecer em público, no mural da Mesa (sem pontos nem ranking);
--   2. férias de verdade: a pessoa marca até quando e a equipe vê na lista de quem está na equipe;
--   3. o termômetro de bem-estar da semana, anônimo de fato;
--   4. a caixa de críticas anônimas;
--   5. o botão de pânico: a conta pode ter sido tomada ou a pessoa está em risco.
-- Anonimato: o termômetro e as críticas não guardam quem respondeu nem a hora exata. Para não deixar a mesma pessoa
-- responder duas vezes (ou encher a caixa), fica só um resumo embaralhado com um sal secreto do banco, que a API não lê.

insert into interno.configuracoes (chave, valor) values ('cuidado_sal', to_jsonb(gen_random_uuid()::text || gen_random_uuid()::text)) on conflict do nothing;

create table if not exists interno.agradecimentos (
  id uuid primary key default gen_random_uuid(),
  de uuid references interno.perfis (id) on delete set null,
  para uuid not null references interno.perfis (id) on delete cascade,
  texto text not null check (char_length(texto) between 3 and 280),
  criado_em timestamptz not null default now()
);
create index if not exists agradecimentos_criado on interno.agradecimentos (criado_em desc);

create table if not exists interno.bem_estar (
  semana date not null,
  marca text not null check (marca ~ '^[0-9a-f]{32}$'),
  nivel smallint not null check (nivel between 1 and 5),
  primary key (semana, marca)
);

create table if not exists interno.criticas (
  id uuid primary key default gen_random_uuid(),
  para text not null default 'geral' check (para ~ '^[a-z_]{2,30}$'),
  texto text not null check (char_length(texto) between 10 and 2000),
  lida boolean not null default false,
  -- Só o dia: a hora exata permitiria cruzar com quem estava no painel naquele minuto.
  dia date not null default current_date
);
create table if not exists interno.criticas_cotas (
  marca text not null check (marca ~ '^[0-9a-f]{32}$'),
  dia date not null,
  total integer not null default 0,
  primary key (marca, dia)
);
revoke all on interno.agradecimentos, interno.bem_estar, interno.criticas, interno.criticas_cotas from public;

/** O resumo embaralhado de uma pessoa num período (semana ou dia), com o sal secreto. */
create or replace function interno.cuidado_marca(p_usuario uuid, p_periodo date) returns text language sql stable security definer set search_path = interno, pg_temp as $$
  select md5(coalesce((select valor #>> '{}' from configuracoes where chave = 'cuidado_sal'), '') || ':' || p_usuario::text || ':' || p_periodo::text)
$$;
create or replace function interno.semana_atual() returns date language sql stable as $$
  select date_trunc('week', (now() at time zone 'America/Sao_Paulo'))::date
$$;
/** Quem cuida da equipe: coordenação, coordenação pedagógica e supervisão. */
create or replace function interno.cuida_da_equipe() returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select interno.coord() or interno.tem('vice') or interno.tem('supervisao')
$$;

/** Agradecer alguém da equipe em público: aparece no mural da Mesa e a pessoa recebe um recado. */
create or replace function public.agradecer(p_para uuid, p_texto text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_texto text := interno.txt(p_texto, 'texto', 3, 280); a agradecimentos;
begin
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  if p_para is null or p_para = v or not interno.voluntario_e(p_para) then perform interno.erro('invalido:para'); end if;
  perform interno.limite('agradecer', 20, 1440);
  insert into agradecimentos (de, para, texto) values (v, p_para, v_texto) returning * into a;
  perform interno.avisar(p_para, format('%s agradeceu você no mural da equipe: “%s”', coalesce((select interno.nome_visto(nome) from perfis where id = v), 'Alguém da equipe'), left(v_texto, 200)));
  return jsonb_build_object('id', a.id);
end $$;

create or replace function public.agradecimentos_listar() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('id', a.id, 'texto', a.texto, 'criado_em', a.criado_em, 'meu', a.de = auth.uid(), 'para_mim', a.para = auth.uid(),
            'de', coalesce((select interno.nome_visto(nome) from perfis where id = a.de), ''), 'para', coalesce((select interno.nome_visto(nome) from perfis where id = a.para), ''))
            order by a.criado_em desc), '[]'::jsonb)
          from (select * from agradecimentos order by criado_em desc limit 30) a);
end $$;

create or replace function public.agradecimento_apagar(p_id uuid) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  delete from agradecimentos where id = p_id and (de = v or interno.cuida_da_equipe());
  if not found then perform interno.erro('nao_encontrado'); end if;
  return jsonb_build_object('ok', true);
end $$;

/** Férias de verdade: até a data (no máximo 120 dias à frente). Sem data, volta. */
create or replace function public.ferias_marcar(p_ate date) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if p_ate is not null and (p_ate < current_date or p_ate > current_date + 120) then perform interno.erro('invalido:ate'); end if;
  update perfis set ferias_ate = p_ate where id = v;
  return jsonb_build_object('ferias_ate', p_ate);
end $$;

create or replace function public.ferias_ver() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  return jsonb_build_object('ferias_ate', (select case when ferias_ate >= current_date then ferias_ate end from perfis where id = interno.eu()));
end $$;

/** O termômetro da semana: de 1 (no limite) a 5 (muito bem). Dá para mudar a resposta na mesma semana. */
create or replace function public.bem_estar_responder(p_nivel integer) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_semana date := interno.semana_atual();
begin
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  if p_nivel is null or p_nivel < 1 or p_nivel > 5 then perform interno.erro('invalido:nivel'); end if;
  insert into bem_estar (semana, marca, nivel) values (v_semana, interno.cuidado_marca(v, v_semana), p_nivel)
  on conflict (semana, marca) do update set nivel = excluded.nivel;
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.bem_estar_situacao() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_semana date := interno.semana_atual();
begin
  return jsonb_build_object('respondeu', exists (select 1 from bem_estar where semana = v_semana and marca = interno.cuidado_marca(v, v_semana)));
end $$;

/** Para quem cuida da equipe: as últimas oito semanas. Com menos de cinco respostas, só o total (senão dá para adivinhar quem). */
create or replace function public.bem_estar_resumo() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  if not interno.cuida_da_equipe() then perform interno.erro('sem_permissao'); end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('semana', s.semana, 'respostas', s.n,
            'media', case when s.n >= 5 then s.media end,
            'baixas', case when s.n >= 5 then s.baixas end) order by s.semana desc), '[]'::jsonb)
          from (select semana, count(*)::int as n, round(avg(nivel), 1) as media, count(*) filter (where nivel <= 2)::int as baixas
                from bem_estar where semana > interno.semana_atual() - 56 group by semana) s);
end $$;

/** A caixa de críticas: anônima. No máximo três por dia por pessoa (contadas por um resumo embaralhado). */
create or replace function public.critica_enviar(p_texto text, p_para text default 'geral') returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_texto text := interno.txt(p_texto, 'texto', 10, 2000); v_para text := coalesce(nullif(btrim(p_para), ''), 'geral'); v_total integer;
begin
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  if v_para !~ '^[a-z_]{2,30}$' then perform interno.erro('invalido:para'); end if;
  insert into criticas_cotas (marca, dia, total) values (interno.cuidado_marca(v, current_date), current_date, 1)
  on conflict (marca, dia) do update set total = criticas_cotas.total + 1 returning total into v_total;
  if v_total > 3 then perform interno.erro('muitos_pedidos'); end if;
  if random() < 0.05 then delete from criticas_cotas where dia < current_date - 2; end if;
  insert into criticas (para, texto) values (v_para, v_texto);
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.criticas_listar() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  if not interno.cuida_da_equipe() then perform interno.erro('sem_permissao'); end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('id', c.id, 'para', c.para, 'texto', c.texto, 'lida', c.lida, 'dia', c.dia) order by c.dia desc, c.lida), '[]'::jsonb)
          from (select * from criticas where dia > current_date - 365 order by dia desc limit 200) c);
end $$;

create or replace function public.critica_marcar(p_id uuid, p_lida boolean) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  if not interno.cuida_da_equipe() then perform interno.erro('sem_permissao'); end if;
  update criticas set lida = coalesce(p_lida, true) where id = p_id;
  if not found then perform interno.erro('nao_encontrado'); end if;
  return jsonb_build_object('ok', true);
end $$;

/**
 * O botão de pânico: encerra as sessões da conta em todos os aparelhos (o navegador sai também) e avisa a coordenação,
 * que deve falar com a pessoa por outro canal antes de qualquer coisa. Fica no registro.
 */
create or replace function public.panico(p_motivo text default '') returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_nome text := coalesce((select interno.nome_visto(nome) from perfis where id = v), 'Alguém da equipe'); v_motivo text := left(btrim(coalesce(p_motivo, '')), 200);
begin
  perform interno.limite('panico', 5, 60);
  perform interno.registrar('panico', v_nome, jsonb_build_object('motivo', v_motivo));
  perform interno.avisar_lideranca(format('%s apertou o botão de pânico no painel%s. As sessões da conta foram encerradas em todos os aparelhos. Fale com a pessoa por outro canal antes de qualquer coisa.',
    v_nome, case when v_motivo <> '' then ' (' || v_motivo || ')' else '' end), v);
  if to_regclass('auth.refresh_tokens') is not null then execute 'delete from auth.refresh_tokens where user_id::text = $1' using v::text; end if;
  if to_regclass('auth.sessions') is not null then execute 'delete from auth.sessions where user_id = $1' using v; end if;
  return jsonb_build_object('ok', true);
end $$;

do $$
declare f record;
begin
  for f in select p.oid::regprocedure as assinatura from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname in ('agradecer', 'agradecimentos_listar', 'agradecimento_apagar', 'ferias_marcar', 'ferias_ver', 'bem_estar_responder',
             'bem_estar_situacao', 'bem_estar_resumo', 'critica_enviar', 'criticas_listar', 'critica_marcar', 'panico') loop
    execute format('revoke all on function %s from public', f.assinatura);
    execute format('grant execute on function %s to anon, authenticated, service_role', f.assinatura);
  end loop;
end $$;
revoke all on function interno.cuidado_marca(uuid, date) from public;

-- ───────────────────────────── Departamentos ─────────────────────────────
-- Cada departamento ganha uma página no painel (seção "Departamentos"): para que serve, a meta do mês, o quadro da
-- semana (a fazer, fazendo, esperando aprovação, feito), os pedidos de outros departamentos com prazo, quem responde,
-- "como trabalhamos" e a passagem de bastão de quem sai de uma função. Os departamentos são os mesmos das conversas
-- (interno.no_departamento): jornalismo (a Comunicação), design, educacao, mentoria, curadoria, revisao, traducao,
-- mediacao, desenvolvimento, saude e coordenacao. Quem responde pelo departamento: o representante dele, a
-- coordenação e a coordenação pedagógica.

create table if not exists interno.departamentos_info (
  id text primary key check (id in ('jornalismo', 'design', 'educacao', 'mentoria', 'curadoria', 'revisao', 'traducao', 'mediacao', 'desenvolvimento', 'saude', 'coordenacao')),
  descricao text not null default '' check (char_length(descricao) <= 400),
  como text not null default '' check (char_length(como) <= 6000),
  meta_titulo text not null default '' check (char_length(meta_titulo) <= 80),
  meta_alvo integer check (meta_alvo is null or meta_alvo between 1 and 100000),
  meta_feito integer not null default 0 check (meta_feito between 0 and 100000),
  atualizado_em timestamptz not null default now(),
  atualizado_por uuid references interno.perfis (id) on delete set null
);

create table if not exists interno.departamento_pedidos (
  id uuid primary key default gen_random_uuid(),
  de text not null check (de ~ '^[a-z_]{2,30}$'),
  para text not null references interno.departamentos_info (id) on delete cascade,
  autor uuid references interno.perfis (id) on delete set null,
  titulo text not null check (char_length(titulo) between 3 and 140),
  detalhe text not null default '' check (char_length(detalhe) <= 2000),
  prazo date,
  status text not null default 'aberto' check (status in ('aberto', 'aceito', 'feito', 'recusado')),
  responsavel uuid references interno.perfis (id) on delete set null,
  resposta text not null default '' check (char_length(resposta) <= 1000),
  criado_em timestamptz not null default now(),
  atualizado_em timestamptz not null default now()
);
create index if not exists departamento_pedidos_para on interno.departamento_pedidos (para, status, criado_em desc);

create table if not exists interno.departamento_quadro (
  id uuid primary key default gen_random_uuid(),
  departamento text not null references interno.departamentos_info (id) on delete cascade,
  titulo text not null check (char_length(titulo) between 3 and 140),
  etiqueta text not null default '' check (char_length(etiqueta) <= 30),
  coluna text not null default 'fazer' check (coluna in ('fazer', 'fazendo', 'aprovacao', 'feito')),
  dono uuid references interno.perfis (id) on delete set null,
  prazo date,
  pedido uuid references interno.departamento_pedidos (id) on delete set null,
  criado_por uuid references interno.perfis (id) on delete set null,
  criado_em timestamptz not null default now(),
  atualizado_em timestamptz not null default now()
);
create index if not exists departamento_quadro_dep on interno.departamento_quadro (departamento, coluna, atualizado_em desc);

-- A passagem de bastão: quem sai de uma função (ou entra de férias longas) deixa o que estava fazendo, onde estão as
-- coisas e quem procurar. Fica guardada para quem chega.
create table if not exists interno.departamento_bastoes (
  id uuid primary key default gen_random_uuid(),
  departamento text not null references interno.departamentos_info (id) on delete cascade,
  autor uuid references interno.perfis (id) on delete set null,
  texto text not null check (char_length(texto) between 10 and 4000),
  criado_em timestamptz not null default now()
);
revoke all on interno.departamentos_info, interno.departamento_pedidos, interno.departamento_quadro, interno.departamento_bastoes from public;

insert into interno.departamentos_info (id, descricao) values
  ('jornalismo', 'Jornal Revolucionário Lúcia, podcast, rádio, Instagram e divulgação. Fazemos o instituto chegar a quem trabalha.'),
  ('design', 'Cartazes, capas, posts e a identidade do instituto, sempre com a marca de sempre.'),
  ('educacao', 'As aulas, as trilhas e as disciplinas: quem escreve, grava e dá aula.'),
  ('mentoria', 'O reforço: dúvidas de estudantes respondidas com calma.'),
  ('curadoria', 'O acervo e a decisão final sobre o que vai ao ar.'),
  ('revisao', 'A leitura atenta antes de publicar: conteúdo, fontes e linguagem simples.'),
  ('traducao', 'As aulas em outros idiomas.'),
  ('mediacao', 'A Comunidade, o Mural dos Trabalhadores e a Gaveta Aberta em ordem e acolhedores.'),
  ('desenvolvimento', 'O site e o painel: erros, melhorias e segurança.'),
  ('saude', 'A vitrine de profissionais de saúde voluntários. Área sensível.'),
  ('coordenacao', 'A coordenação do instituto: pessoas, decisões e prestação de contas.')
on conflict (id) do nothing;

/** Quem responde pelo departamento: o representante dele, a coordenação e a coordenação pedagógica. */
create or replace function interno.responde_departamento(p_departamento text) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select interno.coord() or interno.tem('vice')
    or (interno.sessao_confiavel() and exists (select 1 from papeis where usuario = auth.uid() and papel = 'representante' and disciplina = p_departamento))
$$;

/** Quem é do departamento de fato (sem a coordenação e a supervisão, que entram em todos). */
create or replace function interno.membro_direto(p_usuario uuid, p_departamento text) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select exists (select 1 from papeis p join perfis f on f.id = p.usuario where p.usuario = p_usuario and not f.suspenso and (
    p.papel = p_departamento or (p.papel = 'representante' and p.disciplina = p_departamento)
    or (p_departamento = 'jornalismo' and p.papel = 'marketing') or (p_departamento = 'design' and p.papel = 'marketing')
    or (p_departamento = 'educacao' and p.papel = 'educacao_secundaria') or (p_departamento = 'coordenacao' and p.papel in ('coordenacao', 'vice'))))
$$;

create or replace function interno.departamento_pedido_json(x interno.departamento_pedidos) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select jsonb_build_object('id', x.id, 'de', x.de, 'para', x.para, 'titulo', x.titulo, 'detalhe', x.detalhe, 'prazo', x.prazo, 'status', x.status, 'resposta', x.resposta,
    'criado_em', x.criado_em, 'atualizado_em', x.atualizado_em, 'meu', x.autor = auth.uid(),
    'autor', coalesce((select interno.nome_visto(nome) from perfis where id = x.autor), ''),
    'responsavel', coalesce((select interno.nome_visto(nome) from perfis where id = x.responsavel), ''))
$$;

/** A lista dos departamentos, com quantas pessoas e quantos pedidos abertos cada um tem, e os meus. */
create or replace function public.departamentos_resumo() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('id', d.id, 'descricao', d.descricao,
            'pessoas', (select count(*) from perfis f where interno.membro_direto(f.id, d.id)),
            'pedidos', (select count(*) from departamento_pedidos p where p.para = d.id and p.status in ('aberto', 'aceito')),
            'meu', interno.membro_direto(auth.uid(), d.id), 'respondo', interno.responde_departamento(d.id)) order by d.id), '[]'::jsonb)
          from departamentos_info d);
end $$;

/** Tudo de um departamento: a página inteira. Qualquer pessoa da equipe lê (os departamentos trabalham juntos). */
create or replace function public.departamento_ver(p_id text) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare d departamentos_info;
begin
  perform interno.eu();
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  select * into d from departamentos_info where id = p_id;
  if not found then perform interno.erro('nao_encontrado'); end if;
  return jsonb_build_object(
    'id', d.id, 'descricao', d.descricao, 'como', d.como, 'meta_titulo', d.meta_titulo, 'meta_alvo', d.meta_alvo, 'meta_feito', d.meta_feito, 'atualizado_em', d.atualizado_em,
    'meu', interno.membro_direto(auth.uid(), d.id), 'respondo', interno.responde_departamento(d.id),
    'pessoas', (select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'nome', interno.nome_visto(f.nome), 'avatar', f.avatar,
                  'responde', exists (select 1 from papeis r where r.usuario = f.id and r.papel = 'representante' and r.disciplina = d.id),
                  'ferias_ate', case when f.ferias_ate >= current_date then f.ferias_ate end,
                  'oficios', to_jsonb(f.oficios),
                  -- Desde quando a pessoa está nesta função (para o rodízio: depois de um ano, ensinar alguém).
                  'desde', (select min(p.criado_em) from papeis p where p.usuario = f.id and (p.papel = d.id or p.disciplina = d.id or (d.id = 'jornalismo' and p.papel = 'marketing') or (d.id = 'coordenacao' and p.papel in ('coordenacao', 'vice')))),
                  'papeis', (select jsonb_agg(jsonb_build_object('papel', p.papel, 'disciplina', p.disciplina)) from papeis p where p.usuario = f.id))
                  order by exists (select 1 from papeis r where r.usuario = f.id and r.papel = 'representante' and r.disciplina = d.id) desc, f.nome), '[]'::jsonb)
                from perfis f where interno.membro_direto(f.id, d.id)),
    'recebidos', (select coalesce(jsonb_agg(interno.departamento_pedido_json(x) order by x.status = 'aberto' desc, x.prazo nulls last, x.criado_em desc), '[]'::jsonb)
                  from (select * from departamento_pedidos where para = d.id and (status in ('aberto', 'aceito') or atualizado_em > now() - interval '30 days') limit 100) x),
    'enviados', (select coalesce(jsonb_agg(interno.departamento_pedido_json(x) order by x.criado_em desc), '[]'::jsonb)
                 from (select * from departamento_pedidos where de = d.id and (status in ('aberto', 'aceito') or atualizado_em > now() - interval '30 days') limit 100) x),
    'quadro', (select coalesce(jsonb_agg(jsonb_build_object('id', q.id, 'titulo', q.titulo, 'etiqueta', q.etiqueta, 'coluna', q.coluna, 'prazo', q.prazo, 'pedido', q.pedido,
                 'dono', q.dono, 'dono_nome', coalesce((select interno.nome_visto(nome) from perfis where id = q.dono), ''), 'atualizado_em', q.atualizado_em)
                 order by q.coluna, q.prazo nulls last, q.atualizado_em desc), '[]'::jsonb)
               from departamento_quadro q where q.departamento = d.id and (q.coluna <> 'feito' or q.atualizado_em > now() - interval '14 days')),
    'feitos_no_mes', (select count(*) from departamento_quadro q where q.departamento = d.id and q.coluna = 'feito' and q.atualizado_em >= date_trunc('month', now())),
    'bastoes', (select coalesce(jsonb_agg(jsonb_build_object('id', b.id, 'texto', b.texto, 'criado_em', b.criado_em, 'meu', b.autor = auth.uid(),
                  'autor', coalesce((select interno.nome_visto(nome) from perfis where id = b.autor), '')) order by b.criado_em desc), '[]'::jsonb)
                from (select * from departamento_bastoes where departamento = d.id order by criado_em desc limit 20) b));
end $$;

/** Quem responde pelo departamento muda a apresentação, o "como trabalhamos" e a meta do mês. */
create or replace function public.departamento_salvar(p_id text, p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not interno.responde_departamento(p_id) then perform interno.erro('sem_permissao'); end if;
  update departamentos_info set
    descricao = interno.txt(coalesce(p ->> 'descricao', descricao), 'descricao', 0, 400),
    como = interno.txt(coalesce(p ->> 'como', como), 'como', 0, 6000),
    meta_titulo = interno.txt(coalesce(p ->> 'meta_titulo', meta_titulo), 'meta_titulo', 0, 80),
    meta_alvo = case when p ? 'meta_alvo' then nullif((p ->> 'meta_alvo')::integer, 0) else meta_alvo end,
    meta_feito = case when p ? 'meta_feito' then greatest(0, coalesce((p ->> 'meta_feito')::integer, 0)) else meta_feito end,
    atualizado_em = now(), atualizado_por = v
  where id = p_id;
  if not found then perform interno.erro('nao_encontrado'); end if;
  perform interno.registrar('departamento_salvo', p_id, '{}'::jsonb);
  return public.departamento_ver(p_id);
exception when invalid_text_representation or numeric_value_out_of_range then perform interno.erro('invalido:meta');
end $$;

/** Pedir algo a outro departamento, com prazo. Quem responde pelo departamento que recebe é avisado. */
create or replace function public.departamento_pedir(p_para text, p_de text, p_titulo text, p_detalhe text default '', p_prazo date default null) returns jsonb
language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); x departamento_pedidos; r record;
begin
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  if not exists (select 1 from departamentos_info where id = p_para) then perform interno.erro('invalido:para'); end if;
  if coalesce(p_de, '') !~ '^[a-z_]{2,30}$' then perform interno.erro('invalido:de'); end if;
  if p_prazo is not null and (p_prazo < current_date or p_prazo > current_date + 365) then perform interno.erro('invalido:prazo'); end if;
  perform interno.limite('departamento_pedir', 30, 1440);
  insert into departamento_pedidos (de, para, autor, titulo, detalhe, prazo)
  values (p_de, p_para, v, interno.txt(p_titulo, 'titulo', 3, 140), interno.txt(p_detalhe, 'detalhe', 0, 2000), p_prazo)
  returning * into x;
  for r in select distinct p.usuario from papeis p where p.papel = 'representante' and p.disciplina = p_para and p.usuario <> v loop
    perform interno.avisar(r.usuario, format('Pedido novo para o departamento: “%s”%s. Veja em Departamentos.', left(x.titulo, 100), case when x.prazo is not null then ' (prazo ' || to_char(x.prazo, 'DD/MM') || ')' else '' end));
  end loop;
  return interno.departamento_pedido_json(x);
end $$;

/** Aceitar, marcar como feito ou recusar um pedido: quem é do departamento que recebeu. Quem pediu é avisado. */
create or replace function public.departamento_pedido_mudar(p_id uuid, p_status text, p_resposta text default '') returns jsonb
language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); x departamento_pedidos;
begin
  select * into x from departamento_pedidos where id = p_id for update;
  if not found then perform interno.erro('nao_encontrado'); end if;
  if p_status not in ('aberto', 'aceito', 'feito', 'recusado') then perform interno.erro('invalido:status'); end if;
  if not (interno.membro_direto(v, x.para) or interno.responde_departamento(x.para) or (x.autor = v and p_status = 'aberto')) then perform interno.erro('sem_permissao'); end if;
  if p_status = 'recusado' and char_length(btrim(coalesce(p_resposta, ''))) < 5 then perform interno.erro('invalido:resposta'); end if;
  update departamento_pedidos set status = p_status, resposta = left(coalesce(nullif(btrim(p_resposta), ''), resposta), 1000),
    responsavel = case when p_status in ('aceito', 'feito') then coalesce(responsavel, v) else responsavel end, atualizado_em = now()
  where id = p_id returning * into x;
  if x.autor is distinct from v then
    perform interno.avisar(x.autor, format('Seu pedido “%s” foi %s.%s', left(x.titulo, 100),
      case p_status when 'aceito' then 'aceito' when 'feito' then 'feito' when 'recusado' then 'recusado' else 'reaberto' end,
      case when x.resposta <> '' then ' ' || left(x.resposta, 200) else '' end));
  end if;
  return interno.departamento_pedido_json(x);
end $$;

/** O quadro da semana: criar ou mudar um cartão (quem é do departamento ou responde por ele). */
create or replace function public.departamento_quadro_salvar(p_id uuid, p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); q departamento_quadro; v_dep text := coalesce(p ->> 'departamento', ''); v_dono uuid; v_prazo date;
begin
  if p_id is not null then
    select * into q from departamento_quadro where id = p_id for update;
    if not found then perform interno.erro('nao_encontrado'); end if;
    v_dep := q.departamento;
  end if;
  if not exists (select 1 from departamentos_info where id = v_dep) then perform interno.erro('invalido:departamento'); end if;
  if not (interno.membro_direto(v, v_dep) or interno.responde_departamento(v_dep)) then perform interno.erro('sem_permissao'); end if;
  begin
    v_dono := nullif(p ->> 'dono', '')::uuid;
    v_prazo := nullif(p ->> 'prazo', '')::date;
  exception when others then perform interno.erro('invalido:cartao');
  end;
  if v_dono is not null and not interno.membro_direto(v_dono, v_dep) and not interno.no_departamento(v_dono, v_dep) then perform interno.erro('invalido:dono'); end if;
  if coalesce(p ->> 'coluna', 'fazer') not in ('fazer', 'fazendo', 'aprovacao', 'feito') then perform interno.erro('invalido:coluna'); end if;
  if p_id is null then
    perform interno.limite('departamento_quadro', 120, 1440);
    insert into departamento_quadro (departamento, titulo, etiqueta, coluna, dono, prazo, pedido, criado_por)
    values (v_dep, interno.txt(p ->> 'titulo', 'titulo', 3, 140), interno.txt(coalesce(p ->> 'etiqueta', ''), 'etiqueta', 0, 30), coalesce(p ->> 'coluna', 'fazer'), v_dono, v_prazo,
            (select id from departamento_pedidos where id = nullif(p ->> 'pedido', '')::uuid and para = v_dep), v)
    returning * into q;
  else
    update departamento_quadro set titulo = interno.txt(coalesce(p ->> 'titulo', titulo), 'titulo', 3, 140), etiqueta = interno.txt(coalesce(p ->> 'etiqueta', etiqueta), 'etiqueta', 0, 30),
      coluna = coalesce(p ->> 'coluna', coluna), dono = case when p ? 'dono' then v_dono else dono end, prazo = case when p ? 'prazo' then v_prazo else prazo end, atualizado_em = now()
    where id = p_id returning * into q;
  end if;
  -- Cartão de um pedido que chegou ao "feito": o pedido também fica feito (e quem pediu é avisado).
  if q.coluna = 'feito' and q.pedido is not null and exists (select 1 from departamento_pedidos where id = q.pedido and status in ('aberto', 'aceito')) then
    perform public.departamento_pedido_mudar(q.pedido, 'feito', '');
  end if;
  return jsonb_build_object('id', q.id, 'coluna', q.coluna);
end $$;

create or replace function public.departamento_quadro_apagar(p_id uuid) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); q departamento_quadro;
begin
  select * into q from departamento_quadro where id = p_id;
  if not found then perform interno.erro('nao_encontrado'); end if;
  if not (q.criado_por = v or interno.responde_departamento(q.departamento)) then perform interno.erro('sem_permissao'); end if;
  delete from departamento_quadro where id = p_id;
  return jsonb_build_object('ok', true);
end $$;

/** Deixar a passagem de bastão: quem é do departamento (ou acabou de sair dele, até 30 dias depois). */
create or replace function public.departamento_bastao_deixar(p_departamento text, p_texto text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); b departamento_bastoes;
begin
  if not exists (select 1 from departamentos_info where id = p_departamento) then perform interno.erro('invalido:departamento'); end if;
  if not (interno.membro_direto(v, p_departamento) or interno.responde_departamento(p_departamento)
          or exists (select 1 from papeis_historico h where h.usuario = v and (h.papel = p_departamento or h.disciplina = p_departamento) and h.removido_em > now() - interval '30 days')) then
    perform interno.erro('sem_permissao');
  end if;
  perform interno.limite('departamento_bastao', 10, 1440);
  insert into departamento_bastoes (departamento, autor, texto) values (p_departamento, v, interno.txt(p_texto, 'texto', 10, 4000)) returning * into b;
  return jsonb_build_object('id', b.id);
end $$;

do $$
declare f record;
begin
  for f in select p.oid::regprocedure as assinatura from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname in ('departamentos_resumo', 'departamento_ver', 'departamento_salvar', 'departamento_pedir', 'departamento_pedido_mudar',
             'departamento_quadro_salvar', 'departamento_quadro_apagar', 'departamento_bastao_deixar') loop
    execute format('revoke all on function %s from public', f.assinatura);
    execute format('grant execute on function %s to anon, authenticated, service_role', f.assinatura);
  end loop;
end $$;

-- ───────────────────────────── Assembleias e votações ─────────────────────────────
-- A equipe decide junto. A coordenação e a coordenação pedagógica abrem votações para toda a equipe; o representante de
-- um departamento, para o departamento dele. O voto secreto é secreto de fato: o banco guarda que a pessoa votou (um
-- resumo embaralhado com o sal secreto, para ninguém votar duas vezes) separado do voto, sem nada que ligue um ao outro.
-- O resultado só aparece depois do fim da votação (durante, só quantos votaram), para ninguém ir atrás da maioria.

create table if not exists interno.votacoes (
  id uuid primary key default gen_random_uuid(),
  titulo text not null check (char_length(titulo) between 5 and 160),
  descricao text not null default '' check (char_length(descricao) <= 4000),
  opcoes text[] not null check (cardinality(opcoes) between 2 and 8),
  departamento text check (departamento is null or departamento ~ '^[a-z_]{2,30}$'),
  secreta boolean not null default true,
  encerra_em timestamptz not null,
  encerrada_em timestamptz,
  criada_por uuid references interno.perfis (id) on delete set null,
  criado_em timestamptz not null default now()
);
create table if not exists interno.votacao_presencas (
  votacao uuid not null references interno.votacoes (id) on delete cascade,
  marca text not null check (marca ~ '^[0-9a-f]{32}$'),
  primary key (votacao, marca)
);
create table if not exists interno.votacao_votos (
  id uuid primary key default gen_random_uuid(),
  votacao uuid not null references interno.votacoes (id) on delete cascade,
  opcao smallint not null check (opcao between 0 and 7),
  -- Só no voto aberto: quem votou em quê aparece no resultado.
  usuario uuid references interno.perfis (id) on delete set null
);
create index if not exists votacao_votos_votacao on interno.votacao_votos (votacao);
revoke all on interno.votacoes, interno.votacao_presencas, interno.votacao_votos from public;

/** Esta pessoa vota nesta votação? Toda a equipe, ou quem é do departamento (e quem responde por ele). */
create or replace function interno.vota_em(v interno.votacoes, p_usuario uuid) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select interno.voluntario_e(p_usuario) and (v.departamento is null or interno.membro_direto(p_usuario, v.departamento)
    or exists (select 1 from papeis p where p.usuario = p_usuario and (p.papel in ('coordenacao', 'vice') or (p.papel = 'representante' and p.disciplina = v.departamento))))
$$;

/** A marca de presença de uma pessoa numa votação (o sal secreto e a votação; nada que leve à pessoa sem o sal). */
create or replace function interno.votacao_marca(p_votacao uuid, p_usuario uuid) returns text language sql stable security definer set search_path = interno, pg_temp as $$
  select md5(coalesce((select valor #>> '{}' from configuracoes where chave = 'cuidado_sal'), '') || ':voto:' || p_votacao::text || ':' || coalesce(p_usuario::text, ''))
$$;
revoke all on function interno.votacao_marca(uuid, uuid) from public;

create or replace function interno.votacao_json(v interno.votacoes) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select jsonb_build_object('id', v.id, 'titulo', v.titulo, 'descricao', v.descricao, 'opcoes', to_jsonb(v.opcoes), 'departamento', v.departamento, 'secreta', v.secreta,
    'encerra_em', v.encerra_em, 'terminou_em', least(coalesce(v.encerrada_em, v.encerra_em), v.encerra_em), 'encerrada', v.encerrada_em is not null or v.encerra_em <= now(), 'criado_em', v.criado_em,
    'criada_por', coalesce((select interno.nome_visto(nome) from perfis where id = v.criada_por), ''),
    'minha', v.criada_por = auth.uid(),
    'posso_votar', interno.vota_em(v, auth.uid()),
    'votei', exists (select 1 from votacao_presencas p where p.votacao = v.id and p.marca = interno.votacao_marca(v.id, auth.uid())),
    'votantes', (select count(*) from votacao_presencas p where p.votacao = v.id),
    'aptos', (select count(*) from perfis f where interno.vota_em(v, f.id)),
    'resultado', case when v.encerrada_em is not null or v.encerra_em <= now() then
      (select jsonb_agg(jsonb_build_object('opcao', o.i - 1, 'texto', o.t, 'votos', (select count(*) from votacao_votos w where w.votacao = v.id and w.opcao = o.i - 1),
         'quem', case when not v.secreta then (select coalesce(jsonb_agg(interno.nome_visto(f.nome) order by f.nome), '[]'::jsonb) from votacao_votos w join perfis f on f.id = w.usuario where w.votacao = v.id and w.opcao = o.i - 1) end)
         order by o.i)
       from unnest(v.opcoes) with ordinality as o(t, i)) end)
$$;

create or replace function public.votacoes_listar() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  return (select coalesce(jsonb_agg(interno.votacao_json(v) order by (v.encerrada_em is null and v.encerra_em > now()) desc, v.encerra_em desc), '[]'::jsonb)
          from votacoes v where v.criado_em > now() - interval '365 days' and (v.departamento is null or interno.vota_em(v, auth.uid()) or interno.coord() or interno.tem('vice')));
end $$;

/** Abrir uma votação: a coordenação (para a equipe ou um departamento) ou o representante (para o departamento dele). */
create or replace function public.votacao_criar(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); x votacoes; v_dep text := nullif(btrim(coalesce(p ->> 'departamento', '')), ''); v_opcoes text[]; v_fim timestamptz;
begin
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  if not (interno.coord() or interno.tem('vice') or (v_dep is not null and interno.responde_departamento(v_dep))) then perform interno.erro('sem_permissao'); end if;
  select coalesce(array_agg(btrim(o #>> '{}')) filter (where btrim(o #>> '{}') <> ''), '{}') into v_opcoes from jsonb_array_elements(coalesce(p -> 'opcoes', '[]'::jsonb)) o;
  if cardinality(v_opcoes) < 2 or cardinality(v_opcoes) > 8 or exists (select 1 from unnest(v_opcoes) t where char_length(t) > 120) then perform interno.erro('invalido:opcoes'); end if;
  begin
    v_fim := (p ->> 'encerra_em')::timestamptz;
  exception when others then perform interno.erro('invalido:encerra_em');
  end;
  if v_fim is null or v_fim < now() + interval '1 hour' or v_fim > now() + interval '60 days' then perform interno.erro('invalido:encerra_em'); end if;
  perform interno.limite('votacao_criar', 10, 1440);
  insert into votacoes (titulo, descricao, opcoes, departamento, secreta, encerra_em, criada_por)
  values (interno.txt(p ->> 'titulo', 'titulo', 5, 160), interno.txt(coalesce(p ->> 'descricao', ''), 'descricao', 0, 4000), v_opcoes, v_dep, coalesce((p ->> 'secreta')::boolean, true), v_fim, v)
  returning * into x;
  perform interno.registrar('votacao_aberta', x.titulo, jsonb_build_object('id', x.id, 'departamento', v_dep));
  insert into avisos (para, texto)
  select f.id, left(format('Votação aberta%s: “%s”. Vote até %s, em Assembleias.', case when v_dep is not null then ' no departamento' else '' end, x.titulo, to_char(x.encerra_em at time zone 'America/Sao_Paulo', 'DD/MM HH24:MI')), 500)
  from perfis f where f.id <> v and interno.vota_em(x, f.id);
  return interno.votacao_json(x);
end $$;

/** Votar uma vez. No voto secreto, a presença e o voto ficam em lugares separados, sem ligação. */
create or replace function public.votar(p_id uuid, p_opcao integer) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); x votacoes;
begin
  select * into x from votacoes where id = p_id;
  if not found then perform interno.erro('nao_encontrado'); end if;
  if x.encerrada_em is not null or x.encerra_em <= now() then perform interno.erro('encerrada'); end if;
  if not interno.vota_em(x, v) then perform interno.erro('sem_permissao'); end if;
  if p_opcao is null or p_opcao < 0 or p_opcao >= cardinality(x.opcoes) then perform interno.erro('invalido:opcao'); end if;
  insert into votacao_presencas (votacao, marca) values (x.id, interno.votacao_marca(x.id, v)) on conflict do nothing;
  if not found then perform interno.erro('ja_votou'); end if;
  insert into votacao_votos (votacao, opcao, usuario) values (x.id, p_opcao, case when x.secreta then null else v end);
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.votacao_encerrar(p_id uuid) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); x votacoes;
begin
  select * into x from votacoes where id = p_id for update;
  if not found then perform interno.erro('nao_encontrado'); end if;
  if not (x.criada_por = v or interno.coord()) then perform interno.erro('sem_permissao'); end if;
  update votacoes set encerrada_em = coalesce(encerrada_em, now()) where id = p_id returning * into x;
  perform interno.registrar('votacao_encerrada', x.titulo, jsonb_build_object('id', x.id));
  return interno.votacao_json(x);
end $$;

-- ───────────────────────────── Banco de pautas e calendário editorial ─────────────────────────────
-- Todas as ideias de matéria, episódio, post, aula e vídeo num lugar só, com quem cuida e a data prevista; e o
-- calendário único que junta as pautas, os posts da divulgação, as aulas ao vivo e as reuniões.

create table if not exists interno.pautas (
  id uuid primary key default gen_random_uuid(),
  titulo text not null check (char_length(titulo) between 3 and 160),
  descricao text not null default '' check (char_length(descricao) <= 3000),
  tipo text not null default 'jornal' check (tipo in ('jornal', 'podcast', 'instagram', 'aula', 'video', 'radio', 'outro')),
  status text not null default 'ideia' check (status in ('ideia', 'apurando', 'produzindo', 'revisao', 'publicada', 'descartada')),
  responsavel uuid references interno.perfis (id) on delete set null,
  data_prevista date,
  link text not null default '' check (link = '' or (char_length(link) <= 500 and link ~ '^https://[^\s]{3,}$')),
  criado_por uuid references interno.perfis (id) on delete set null,
  criado_em timestamptz not null default now(),
  atualizado_em timestamptz not null default now()
);
create index if not exists pautas_status on interno.pautas (status, data_prevista);
revoke all on interno.pautas from public;

/** O departamento de cada tipo de pauta: quem cuida dele também mexe em qualquer pauta do tipo. */
create or replace function interno.pauta_departamento(p_tipo text) returns text language sql immutable as $$
  select case p_tipo when 'aula' then 'educacao' when 'video' then 'educacao' else 'jornalismo' end
$$;

create or replace function interno.pauta_json(x interno.pautas) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select jsonb_build_object('id', x.id, 'titulo', x.titulo, 'descricao', x.descricao, 'tipo', x.tipo, 'status', x.status, 'data_prevista', x.data_prevista, 'link', x.link,
    'responsavel', x.responsavel, 'responsavel_nome', coalesce((select interno.nome_visto(nome) from perfis where id = x.responsavel), ''),
    'criado_por', coalesce((select interno.nome_visto(nome) from perfis where id = x.criado_por), ''), 'criado_em', x.criado_em, 'atualizado_em', x.atualizado_em,
    'mexo', x.criado_por = auth.uid() or x.responsavel = auth.uid() or interno.membro_direto(auth.uid(), interno.pauta_departamento(x.tipo)) or interno.responde_departamento(interno.pauta_departamento(x.tipo)))
$$;

create or replace function public.pautas_listar() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  return (select coalesce(jsonb_agg(interno.pauta_json(x) order by x.data_prevista nulls last, x.atualizado_em desc), '[]'::jsonb)
          from pautas x where x.status not in ('publicada', 'descartada') or x.atualizado_em > now() - interval '60 days');
end $$;

/** Propor (qualquer pessoa da equipe) ou mudar uma pauta (quem criou, quem cuida dela e o departamento do tipo). */
create or replace function public.pauta_salvar(p_id uuid, p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); x pautas; v_resp uuid; v_data date;
begin
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  begin
    v_resp := nullif(p ->> 'responsavel', '')::uuid;
    v_data := nullif(p ->> 'data_prevista', '')::date;
  exception when others then perform interno.erro('invalido:pauta');
  end;
  if v_resp is not null and not interno.voluntario_e(v_resp) then perform interno.erro('invalido:responsavel'); end if;
  if p_id is null then
    perform interno.limite('pauta_salvar', 60, 1440);
    insert into pautas (titulo, descricao, tipo, status, responsavel, data_prevista, link, criado_por)
    values (interno.txt(p ->> 'titulo', 'titulo', 3, 160), interno.txt(coalesce(p ->> 'descricao', ''), 'descricao', 0, 3000), coalesce(p ->> 'tipo', 'jornal'),
            coalesce(p ->> 'status', 'ideia'), v_resp, v_data, btrim(coalesce(p ->> 'link', '')), v)
    returning * into x;
  else
    select * into x from pautas where id = p_id for update;
    if not found then perform interno.erro('nao_encontrado'); end if;
    if not (x.criado_por = v or x.responsavel = v or interno.membro_direto(v, interno.pauta_departamento(x.tipo)) or interno.responde_departamento(interno.pauta_departamento(x.tipo))) then
      perform interno.erro('sem_permissao');
    end if;
    update pautas set titulo = interno.txt(coalesce(p ->> 'titulo', titulo), 'titulo', 3, 160), descricao = interno.txt(coalesce(p ->> 'descricao', descricao), 'descricao', 0, 3000),
      tipo = coalesce(p ->> 'tipo', tipo), status = coalesce(p ->> 'status', status), responsavel = case when p ? 'responsavel' then v_resp else responsavel end,
      data_prevista = case when p ? 'data_prevista' then v_data else data_prevista end, link = case when p ? 'link' then btrim(coalesce(p ->> 'link', '')) else link end, atualizado_em = now()
    where id = p_id returning * into x;
  end if;
  if x.responsavel is not null and x.responsavel <> v then
    perform interno.avisar(x.responsavel, format('Você está cuidando da pauta “%s”. Veja em Pautas e calendário.', left(x.titulo, 100)));
  end if;
  return interno.pauta_json(x);
exception when check_violation then perform interno.erro('invalido:pauta');
end $$;

/** O calendário único: pautas com data, posts da divulgação, aulas ao vivo e reuniões, de um período (até 120 dias). */
create or replace function public.calendario_equipe(p_de date, p_ate date) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v_de date := coalesce(p_de, current_date); v_ate date := least(coalesce(p_ate, current_date + 30), coalesce(p_de, current_date) + 120);
begin
  perform interno.eu();
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  return coalesce((select jsonb_agg(e order by e ->> 'dia', e ->> 'hora') from (
    select jsonb_build_object('tipo', 'pauta', 'subtipo', x.tipo, 'id', x.id, 'titulo', x.titulo, 'dia', x.data_prevista, 'hora', '', 'situacao', x.status,
             'quem', coalesce((select interno.nome_visto(nome) from perfis where id = x.responsavel), '')) as e
      from pautas x where x.data_prevista between v_de and v_ate and x.status <> 'descartada'
    union all
    select jsonb_build_object('tipo', 'post', 'subtipo', d.formato, 'id', d.id, 'titulo', d.titulo, 'dia', d.data_prevista, 'hora', '', 'situacao', d.situacao, 'quem', '')
      from divulgacao d where d.data_prevista between v_de and v_ate
    union all
    select jsonb_build_object('tipo', 'aula', 'subtipo', a.disciplina, 'id', a.id, 'titulo', a.titulo, 'dia', (a.inicio at time zone 'America/Sao_Paulo')::date,
             'hora', to_char(a.inicio at time zone 'America/Sao_Paulo', 'HH24:MI'), 'situacao', a.status, 'quem', coalesce((select interno.nome_visto(nome) from perfis where id = a.educador), ''))
      from aulas_ao_vivo a where a.status <> 'cancelada' and (a.inicio at time zone 'America/Sao_Paulo')::date between v_de and v_ate
    union all
    select jsonb_build_object('tipo', 'reuniao', 'subtipo', r.tipo, 'id', r.id, 'titulo', r.titulo, 'dia', (r.inicio at time zone 'America/Sao_Paulo')::date,
             'hora', to_char(r.inicio at time zone 'America/Sao_Paulo', 'HH24:MI'), 'situacao', r.status, 'quem', '')
      from reunioes r where r.status <> 'cancelada' and (r.inicio at time zone 'America/Sao_Paulo')::date between v_de and v_ate and (interno.reuniao_entra(r) or r.tipo = 'aberta')
  ) eventos), '[]'::jsonb);
end $$;

do $$
declare f record;
begin
  for f in select p.oid::regprocedure as assinatura from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname in ('votacoes_listar', 'votacao_criar', 'votar', 'votacao_encerrar', 'pautas_listar', 'pauta_salvar', 'calendario_equipe') loop
    execute format('revoke all on function %s from public', f.assinatura);
    execute format('grant execute on function %s to anon, authenticated, service_role', f.assinatura);
  end loop;
end $$;

-- ───────────────────────────── Ofícios e chegada ─────────────────────────────
/** Os meus ofícios e quando cheguei à equipe (a primeira função), para a primeira semana guiada. */
create or replace function public.perfil_extras() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  return jsonb_build_object('oficios', (select to_jsonb(oficios) from perfis where id = v), 'chegada', (select min(criado_em) from papeis where usuario = v));
end $$;

/** Guardar os ofícios: até dez, cada um com 2 a 40 caracteres. */
create or replace function public.perfil_oficios_salvar(p_oficios text[]) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_lista text[];
begin
  select coalesce(array_agg(distinct btrim(o)) filter (where btrim(o) <> ''), '{}') into v_lista from unnest(coalesce(p_oficios, '{}')) o;
  if cardinality(v_lista) > 10 or exists (select 1 from unnest(v_lista) o where char_length(o) < 2 or char_length(o) > 40) then perform interno.erro('invalido:oficios'); end if;
  update perfis set oficios = v_lista where id = v;
  return jsonb_build_object('oficios', to_jsonb(v_lista));
end $$;

do $$
declare f record;
begin
  for f in select p.oid::regprocedure as assinatura from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname in ('perfil_extras', 'perfil_oficios_salvar') loop
    execute format('revoke all on function %s from public', f.assinatura);
    execute format('grant execute on function %s to anon, authenticated, service_role', f.assinatura);
  end loop;
end $$;

-- ───────────────────────────── Núcleos e conquistas da equipe ─────────────────────────────
-- O mapa de núcleos: os grupos de estudo que fazem as aulas juntos (no bairro, na escola, no trabalho), por cidade e
-- estado. Só dentro do painel e sem endereço nem nome de participante: núcleo de formação militante é alvo de
-- perseguição, então o painel guarda o mínimo (cidade, tipo, quem da equipe acompanha). As conquistas são da equipe
-- inteira, nunca de uma pessoa: sem ranking.

create table if not exists interno.nucleos (
  id uuid primary key default gen_random_uuid(),
  nome text not null check (char_length(nome) between 3 and 80),
  cidade text not null check (char_length(cidade) between 2 and 80),
  uf text not null check (uf in ('AC','AL','AP','AM','BA','CE','DF','ES','GO','MA','MT','MS','MG','PA','PB','PR','PE','PI','RJ','RN','RS','RO','RR','SC','SP','SE','TO','EX')),
  tipo text not null default 'bairro' check (tipo in ('bairro', 'escola', 'trabalho', 'universidade', 'online', 'outro')),
  encontros text not null default '' check (char_length(encontros) <= 200),
  pessoas integer check (pessoas is null or pessoas between 1 and 500),
  acompanha uuid references interno.perfis (id) on delete set null,
  ativo boolean not null default true,
  criado_por uuid references interno.perfis (id) on delete set null,
  criado_em timestamptz not null default now(),
  atualizado_em timestamptz not null default now()
);
create index if not exists nucleos_uf on interno.nucleos (uf, cidade);
-- O mapa público é opcional e moderado: o núcleo só aparece no site quando a coordenação (ou a vice) publica. Mesmo
-- assim, só o que o núcleo escolheu mostrar: o ponto de encontro público (praça, biblioteca, sindicato) e um contato
-- do próprio núcleo (perfil, grupo), nunca o de uma pessoa.
alter table interno.nucleos add column if not exists publico boolean not null default false;
alter table interno.nucleos add column if not exists ponto text not null default '' check (char_length(ponto) <= 120);
alter table interno.nucleos add column if not exists contato text not null default '' check (contato = '' or contato ~ '^https://[^[:space:]]{4,200}$');
revoke all on interno.nucleos from public;

create or replace function public.nucleos_listar() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('id', n.id, 'nome', n.nome, 'cidade', n.cidade, 'uf', n.uf, 'tipo', n.tipo, 'encontros', n.encontros, 'pessoas', n.pessoas,
            'ativo', n.ativo, 'atualizado_em', n.atualizado_em, 'acompanha', coalesce((select interno.nome_visto(nome) from perfis where id = n.acompanha), ''),
            'publico', n.publico, 'ponto', n.ponto, 'contato', n.contato, 'publica', interno.coord() or interno.tem('vice'),
            'mexo', n.criado_por = auth.uid() or n.acompanha = auth.uid() or interno.coord() or interno.tem('vice'))
            order by n.uf, n.cidade, n.nome), '[]'::jsonb) from nucleos n);
end $$;

/** Cadastrar (qualquer pessoa da equipe, que passa a acompanhar o núcleo) ou mudar (quem cadastrou, quem acompanha, a coordenação). */
create or replace function public.nucleo_salvar(p_id uuid, p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); n nucleos; v_pessoas integer;
begin
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  begin
    v_pessoas := nullif(p ->> 'pessoas', '')::integer;
  exception when others then perform interno.erro('invalido:pessoas');
  end;
  if p_id is null then
    perform interno.limite('nucleo_salvar', 20, 1440);
    insert into nucleos (nome, cidade, uf, tipo, encontros, pessoas, acompanha, criado_por)
    values (interno.txt(p ->> 'nome', 'nome', 3, 80), interno.txt(p ->> 'cidade', 'cidade', 2, 80), upper(coalesce(p ->> 'uf', '')), coalesce(p ->> 'tipo', 'bairro'),
            interno.txt(coalesce(p ->> 'encontros', ''), 'encontros', 0, 200), v_pessoas, v, v)
    returning * into n;
  else
    select * into n from nucleos where id = p_id for update;
    if not found then perform interno.erro('nao_encontrado'); end if;
    if not (n.criado_por = v or n.acompanha = v or interno.coord() or interno.tem('vice')) then perform interno.erro('sem_permissao'); end if;
    -- Pôr no mapa público (ou tirar) é decisão da coordenação ou da vice.
    if p ? 'publico' and coalesce((p ->> 'publico')::boolean, false) <> n.publico and not (interno.coord() or interno.tem('vice')) then perform interno.erro('sem_permissao'); end if;
    update nucleos set ponto = interno.txt(coalesce(p ->> 'ponto', ponto), 'ponto', 0, 120), contato = btrim(coalesce(p ->> 'contato', contato)),
      publico = coalesce((p ->> 'publico')::boolean, publico), nome = interno.txt(coalesce(p ->> 'nome', nome), 'nome', 3, 80), cidade = interno.txt(coalesce(p ->> 'cidade', cidade), 'cidade', 2, 80),
      uf = upper(coalesce(p ->> 'uf', uf)), tipo = coalesce(p ->> 'tipo', tipo), encontros = interno.txt(coalesce(p ->> 'encontros', encontros), 'encontros', 0, 200),
      pessoas = case when p ? 'pessoas' then v_pessoas else pessoas end, ativo = coalesce((p ->> 'ativo')::boolean, ativo), atualizado_em = now()
    where id = p_id returning * into n;
  end if;
  return jsonb_build_object('id', n.id);
exception when check_violation then perform interno.erro('invalido:nucleo');
end $$;

/** As conquistas da equipe inteira: o que o instituto já pôs no ar, no total e neste mês. Nada por pessoa. */
create or replace function public.conquistas_da_equipe() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v_mes timestamptz := date_trunc('month', now());
begin
  perform interno.eu();
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  return jsonb_build_object(
    'aulas', (select count(*) from contribuicoes where tipo = 'aula' and status = 'publicada'),
    'aulas_mes', (select count(*) from contribuicoes where tipo = 'aula' and status in ('aprovada', 'publicada') and revisado_em >= v_mes),
    'materias', (select count(*) from contribuicoes where tipo = 'artigo' and status = 'publicada'),
    'videoaulas', (select count(*) from videoaulas where status = 'aprovada'),
    'horas', coalesce((select round(sum(horas)) from horas where status = 'confirmada'), 0),
    'horas_mes', coalesce((select round(sum(horas)) from horas where status = 'confirmada' and dia >= v_mes::date), 0),
    'pessoas', (select count(distinct usuario) from papeis),
    'pedidos_feitos_mes', (select count(*) from departamento_pedidos where status = 'feito' and atualizado_em >= v_mes),
    'nucleos', (select count(*) from nucleos where ativo));
end $$;

do $$
declare f record;
begin
  for f in select p.oid::regprocedure as assinatura from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname in ('nucleos_listar', 'nucleo_salvar', 'conquistas_da_equipe') loop
    execute format('revoke all on function %s from public', f.assinatura);
    execute format('grant execute on function %s to anon, authenticated, service_role', f.assinatura);
  end loop;
end $$;

-- ───────────────────────────── Conversas no jeito do Stoat: perfil, amigos e convites ─────────────────────────────

/** A presença, a frase de status e a capa do cartão de perfil (de quem está logado). */
create or replace function public.chat_perfil_salvar(p_presenca text, p_frase text, p_capa text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if coalesce(p_presenca, '') not in ('online', 'ausente', 'ocupado', 'invisivel') then perform interno.erro('invalido:presenca'); end if;
  if coalesce(p_capa, '') not in ('vermelho', 'noite', 'ouro', 'verde', 'azul', 'roxo', 'rosa', 'pergaminho') then perform interno.erro('invalido:capa'); end if;
  update perfis set presenca = p_presenca, frase = interno.txt(coalesce(p_frase, ''), 'frase', 0, 80), capa = p_capa where id = v;
  return jsonb_build_object('presenca', p_presenca, 'frase', btrim(coalesce(p_frase, '')), 'capa', p_capa);
end $$;

create or replace function public.chat_perfil_meu() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  return (select jsonb_build_object('presenca', presenca, 'frase', frase, 'capa', capa) from perfis where id = interno.eu());
end $$;

/** Pedir amizade (a quem é da equipe). Se o outro já tinha pedido, a amizade fica aceita na hora. */
create or replace function public.amizade_pedir(p_para uuid) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  if p_para is null or p_para = v or not interno.voluntario_e(p_para) then perform interno.erro('invalido:para'); end if;
  perform interno.limite('amizade_pedir', 40, 1440);
  if exists (select 1 from amizades where de = p_para and para = v) then
    update amizades set aceita = true, aceita_em = coalesce(aceita_em, now()) where de = p_para and para = v;
    perform interno.avisar(p_para, format('%s aceitou a sua amizade nas Conversas. Agora vocês conversam no privado.', coalesce((select interno.nome_visto(nome) from perfis where id = v), 'Alguém')));
    return jsonb_build_object('aceita', true);
  end if;
  insert into amizades (de, para) values (v, p_para) on conflict do nothing;
  if found then
    perform interno.avisar(p_para, format('%s quer ser seu amigo nas Conversas. Aceite em Conversas › Mensagens diretas › Amigos.', coalesce((select interno.nome_visto(nome) from perfis where id = v), 'Alguém')));
  end if;
  return jsonb_build_object('aceita', false);
end $$;

create or replace function public.amizade_responder(p_de uuid, p_aceitar boolean) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if not exists (select 1 from amizades where de = p_de and para = v and not aceita) then perform interno.erro('nao_encontrado'); end if;
  if coalesce(p_aceitar, false) then
    update amizades set aceita = true, aceita_em = now() where de = p_de and para = v;
    perform interno.avisar(p_de, format('%s aceitou a sua amizade nas Conversas. Agora vocês conversam no privado.', coalesce((select interno.nome_visto(nome) from perfis where id = v), 'Alguém')));
  else
    delete from amizades where de = p_de and para = v;
  end if;
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.amizade_desfazer(p_outro uuid) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  delete from amizades where (de = v and para = p_outro) or (de = p_outro and para = v);
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.amizades_listar() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  return jsonb_build_object(
    'amigos', (select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'nome', interno.nome_visto(f.nome), 'avatar', f.avatar, 'frase', f.frase,
                 'presenca', case when f.presenca = 'invisivel' then 'online' else f.presenca end,
                 'online', f.presenca <> 'invisivel' and f.chat_visto and f.visto_em > now() - interval '2 minutes') order by f.nome), '[]'::jsonb)
               from amizades a join perfis f on f.id = case when a.de = v then a.para else a.de end where a.aceita and (a.de = v or a.para = v)),
    'recebidos', (select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'nome', interno.nome_visto(f.nome), 'avatar', f.avatar, 'criado_em', a.criado_em) order by a.criado_em desc), '[]'::jsonb)
                  from amizades a join perfis f on f.id = a.de where a.para = v and not a.aceita),
    'enviados', (select coalesce(jsonb_agg(jsonb_build_object('id', f.id, 'nome', interno.nome_visto(f.nome), 'avatar', f.avatar, 'criado_em', a.criado_em) order by a.criado_em desc), '[]'::jsonb)
                 from amizades a join perfis f on f.id = a.para where a.de = v and not a.aceita));
end $$;

-- Convites para grupos: um código curto que vale alguns dias. Quem entra recebe as chaves da conversa do aparelho de
-- alguém que já está nela (a cifra repassa sozinha), então as mensagens aparecem assim que alguém do grupo abrir o painel.
create table if not exists interno.chat_convites (
  codigo text primary key check (codigo ~ '^[A-Za-z0-9]{10}$'),
  conversa uuid not null references interno.conversas (id) on delete cascade,
  criado_por uuid references interno.perfis (id) on delete set null,
  expira_em timestamptz not null,
  usos integer not null default 0,
  maximo integer check (maximo is null or maximo between 1 and 100),
  criado_em timestamptz not null default now()
);
revoke all on interno.amizades, interno.chat_convites from public;

/** Criar um convite: só para grupo (os canais de departamento seguem a função), por quem pode mudar o grupo. */
create or replace function public.chat_convite_criar(p_conversa uuid, p_dias integer default 7, p_maximo integer default null) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); c conversas; v_codigo text;
begin
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  select * into c from conversas where id = p_conversa;
  if not found or c.tipo <> 'grupo' or c.departamento is not null then perform interno.erro('invalido:conversa'); end if;
  if not exists (select 1 from conversa_membros m where m.conversa = c.id and m.usuario = v and (m.admin or not c.so_admins_mudam)) then perform interno.erro('sem_permissao'); end if;
  if coalesce(p_dias, 7) not between 1 and 30 then perform interno.erro('invalido:dias'); end if;
  perform interno.limite('chat_convite', 20, 1440);
  v_codigo := substr(md5(random()::text || clock_timestamp()::text || v::text), 1, 10);
  insert into chat_convites (codigo, conversa, criado_por, expira_em, maximo) values (v_codigo, c.id, v, now() + make_interval(days => coalesce(p_dias, 7)), p_maximo);
  return jsonb_build_object('codigo', v_codigo, 'expira_em', now() + make_interval(days => coalesce(p_dias, 7)));
end $$;

create or replace function public.chat_convite_ver(p_codigo text) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare k chat_convites;
begin
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  select * into k from chat_convites where codigo = p_codigo;
  if not found or k.expira_em < now() or (k.maximo is not null and k.usos >= k.maximo) then return jsonb_build_object('valido', false); end if;
  return jsonb_build_object('valido', true, 'conversa', k.conversa, 'nome', (select nome from conversas where id = k.conversa),
    'membros', (select count(*) from conversa_membros where conversa = k.conversa), 'ja_estou', exists (select 1 from conversa_membros where conversa = k.conversa and usuario = auth.uid()),
    'de', coalesce((select interno.nome_visto(nome) from perfis where id = k.criado_por), ''));
end $$;

create or replace function public.chat_convite_usar(p_codigo text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); k chat_convites;
begin
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('chat_convite_usar', 30, 60);
  select * into k from chat_convites where codigo = p_codigo for update;
  if not found or k.expira_em < now() or (k.maximo is not null and k.usos >= k.maximo) then perform interno.erro('convite_vencido'); end if;
  if exists (select 1 from conversa_membros where conversa = k.conversa and usuario = v) then return jsonb_build_object('conversa', k.conversa); end if;
  if (select count(*) from conversa_membros where conversa = k.conversa) >= 61 then perform interno.erro('invalido:membros'); end if;
  insert into conversa_membros (conversa, usuario) values (k.conversa, v);
  update chat_convites set usos = usos + 1 where codigo = p_codigo;
  update conversas set movida_em = now() where id = k.conversa;
  perform interno.chat_aviso(k.conversa, 'convite', v, null);
  return jsonb_build_object('conversa', k.conversa);
end $$;

do $$
declare f record;
begin
  for f in select p.oid::regprocedure as assinatura from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname in ('chat_perfil_salvar', 'chat_perfil_meu', 'amizade_pedir', 'amizade_responder', 'amizade_desfazer', 'amizades_listar',
             'chat_convite_criar', 'chat_convite_ver', 'chat_convite_usar') loop
    execute format('revoke all on function %s from public', f.assinatura);
    execute format('grant execute on function %s to anon, authenticated, service_role', f.assinatura);
  end loop;
end $$;

-- ───────────────────────────── Rede Lúcia ─────────────────────────────
-- A Comunidade vira uma pequena rede de formação militante: além do fórum (o lado Reddit), a linha do tempo de posts
-- curtos (o lado Twitter), com respostas em fio, repost com comentário, seguir pessoas, citar aula, obra ou matéria e
-- chamados à ação (ato, mutirão, assembleia) com "Eu vou". Em ordem de tempo, sem algoritmo, sem "em alta" e sem número
-- de seguidores em destaque. Segurança desde o começo:
--   - pseudônimo (o nome que a pessoa escolhe) e perfil invisível opcional;
--   - alcance escolhido em cada post (todos, só quem segue, só a equipe);
--   - aviso de conteúdo; bloquear pessoas;
--   - filtro de CPF, telefone e e-mail;
--   - limite de posts para contas novas;
--   - a mesma moderação automática e a mesma fila da mediação do fórum;
--   - rede para maiores de 16 anos (a pessoa confirma uma vez).

alter table interno.perfis add column if not exists rede_invisivel boolean not null default false;
alter table interno.perfis add column if not exists rede_16 boolean not null default false;
/** Um codinome livre: o pedido, se servir e ninguém usar; senão, o nome de uma lutadora com número. */
create or replace function interno.rede_codinome_livre(p_pedido text default null) returns text language plpgsql volatile security definer set search_path = interno, pg_temp as $$
declare v text := interno.codinome(p_pedido); i integer;
begin
  for i in 1..80 loop
    exit when not exists (select 1 from perfis where interno.rede_chave(rede_codinome) = interno.rede_chave(v));
    v := interno.codinome(null);
  end loop;
  return v;
end $$;

-- Quem já tinha perfil ganha um codinome uma vez: na equipe, um sorteado (o nome do painel é o civil); no resto, o apelido
-- que já usava em público, se servir. Antes de postar de novo, cada pessoa confirma ou troca (rede_codinome_ok).
do $$
declare r record;
begin
  for r in select id, nome from interno.perfis where rede_codinome is null loop
    update interno.perfis set rede_codinome = interno.rede_codinome_livre(case when interno.voluntario_e(r.id) then null else r.nome end) where id = r.id;
  end loop;
end $$;

create table if not exists interno.rede_posts (
  id uuid primary key default gen_random_uuid(),
  autor uuid references interno.perfis (id) on delete cascade,
  texto text not null default '' check (char_length(texto) <= 500),
  comunidade text check (comunidade is null or comunidade ~ '^[a-z0-9-]{2,60}$'),
  resposta_a uuid references interno.rede_posts (id) on delete cascade,
  repost_de uuid references interno.rede_posts (id) on delete cascade,
  cita jsonb,
  chamado jsonb,
  alcance text not null default 'publico' check (alcance in ('publico', 'seguidores', 'equipe')),
  aviso text not null default '' check (char_length(aviso) <= 80),
  oculto boolean not null default false,
  retido boolean not null default false,
  avaliacao text check (avaliacao is null or avaliacao in ('publicada', 'revisao', 'bloqueada', 'revista')),
  motivo text not null default '',
  criado_em timestamptz not null default now(),
  check (char_length(texto) > 0 or repost_de is not null)
);
create index if not exists rede_posts_tempo on interno.rede_posts (criado_em desc);
create index if not exists rede_posts_autor on interno.rede_posts (autor, criado_em desc);
create index if not exists rede_posts_comunidade on interno.rede_posts (comunidade, criado_em desc);
create index if not exists rede_posts_fio on interno.rede_posts (resposta_a, criado_em);
create table if not exists interno.rede_seguindo (quem uuid not null references interno.perfis (id) on delete cascade, segue uuid not null references interno.perfis (id) on delete cascade, criado_em timestamptz not null default now(), primary key (quem, segue), check (quem <> segue));
create table if not exists interno.rede_apoios (post uuid not null references interno.rede_posts (id) on delete cascade, usuario uuid not null references interno.perfis (id) on delete cascade, primary key (post, usuario));
create table if not exists interno.rede_vou (post uuid not null references interno.rede_posts (id) on delete cascade, usuario uuid not null references interno.perfis (id) on delete cascade, primary key (post, usuario));
create table if not exists interno.rede_bloqueios (quem uuid not null references interno.perfis (id) on delete cascade, bloqueado uuid not null references interno.perfis (id) on delete cascade, criado_em timestamptz not null default now(), primary key (quem, bloqueado), check (quem <> bloqueado));
revoke all on interno.rede_posts, interno.rede_seguindo, interno.rede_apoios, interno.rede_vou, interno.rede_bloqueios from public;

/** Um bloqueou o outro (em qualquer direção)? */
create or replace function interno.rede_bloqueado(p_a uuid, p_b uuid) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select p_a is not null and p_b is not null and exists (select 1 from rede_bloqueios where (quem = p_a and bloqueado = p_b) or (quem = p_b and bloqueado = p_a))
$$;

/** Quem está vendo pode ver este post? (oculto só para quem escreveu; alcance; bloqueio.) */
create or replace function interno.rede_ve(p interno.rede_posts) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select (not p.oculto or p.autor = auth.uid())
    and not interno.rede_bloqueado(auth.uid(), p.autor)
    and (p.alcance = 'publico' or p.autor = auth.uid()
         or (p.alcance = 'seguidores' and exists (select 1 from rede_seguindo s where s.quem = auth.uid() and s.segue = p.autor))
         or (p.alcance = 'equipe' and interno.voluntario()))
$$;

-- Em plpgsql (e não sql): ela chama a si mesma para o post original de um repost.
create or replace function interno.rede_post_json(p interno.rede_posts, p_com_original boolean default true) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  return jsonb_build_object('id', p.id, 'texto', p.texto, 'comunidade', p.comunidade, 'criado_em', p.criado_em, 'aviso', p.aviso, 'cita', p.cita, 'chamado', p.chamado,
    'alcance', p.alcance, 'posicao', p.posicao, 'meu', p.autor = auth.uid(), 'retido', case when p.autor = auth.uid() then p.retido or p.oculto else false end,
    'modero', interno.cuida() or exists (select 1 from rede_moderadores m where m.comunidade = p.comunidade and m.usuario = auth.uid())
              or (p.comunidade like 'fechado-%' and exists (select 1 from rede_espaco_membros m where m.espaco = p.comunidade and m.usuario = auth.uid() and m.cuida)),
    'autor', jsonb_build_object('id', p.autor, 'nome', interno.rede_nome(p.autor), 'codinome', true, 'avatar', null, 'equipe', interno.voluntario_e(p.autor)),
    'respostas', (select count(*) from rede_posts r where r.resposta_a = p.id and not r.oculto),
    'apoios', (select count(*) from rede_apoios a where a.post = p.id),
    'apoiei', exists (select 1 from rede_apoios a where a.post = p.id and a.usuario = auth.uid()),
    'vou', case when p.chamado is not null then (select count(*) from rede_vou v where v.post = p.id) end,
    'vou_eu', exists (select 1 from rede_vou v where v.post = p.id and v.usuario = auth.uid()),
    'resposta_a', case when p.resposta_a is not null then (select jsonb_build_object('id', o.id, 'autor', interno.rede_nome(o.autor)) from rede_posts o where o.id = p.resposta_a) end,
    'original', case when p_com_original and p.repost_de is not null then (select case when interno.rede_ve(o) then interno.rede_post_json(o, false) end from rede_posts o where o.id = p.repost_de) end);
end $$;

/** Uma vez só: a rede é para maiores de 16 anos. */
create or replace function public.rede_confirmar_idade() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  update perfis set rede_16 = true where id = interno.eu();
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.rede_config(p_invisivel boolean) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  update perfis set rede_invisivel = coalesce(p_invisivel, false) where id = interno.eu();
  return jsonb_build_object('invisivel', coalesce(p_invisivel, false));
end $$;

create or replace function public.rede_eu() returns jsonb language plpgsql volatile security definer set search_path = interno, pg_temp as $$
begin
  return (select jsonb_build_object('id', id, 'nome', rede_codinome, 'codinome', true, 'codinome_ok', rede_codinome_ok, 'bio', rede_bio,
    'sugestao', coalesce(rede_codinome, interno.rede_codinome_livre(case when interno.voluntario_e(id) then null else nome end)),
    'rede_16', rede_16, 'invisivel', rede_invisivel) from perfis where id = interno.eu());
end $$;

/**
 * Escolher (ou confirmar) o codinome da Rede. De 3 a 30 caracteres, sem endereço nem @, livre (sem repetir, sem contar
 * acento e caixa). Na equipe, não pode ser o nome do painel, o primeiro nome nem começar por ele; ninguém usa o nome de
 * alguém da equipe nem o do instituto.
 */
create or replace function public.rede_codinome_definir(p_codinome text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.eu();
  v_nome text := btrim(regexp_replace(coalesce(p_codinome, ''), '\s+', ' ', 'g'));
  v_chave text; v_civil text;
begin
  perform interno.limite('rede_codinome', 12, 60);
  if char_length(v_nome) < 3 or char_length(v_nome) > 30 or v_nome !~ '^[[:alpha:]0-9][[:alpha:]0-9 .''_-]*$' or v_nome ~* '(https?|www\.|@)' then
    perform interno.erro('invalido:codinome');
  end if;
  v_chave := interno.rede_chave(v_nome);
  if v_chave ~ '(instituto|lucia|moderac|mediac|coordenac|administra|equipe oficial)' then perform interno.erro('codinome_reservado'); end if;
  if interno.voluntario_e(v) then
    v_civil := interno.rede_chave((select nome from perfis where id = v));
    if v_civil <> '' and (v_chave = v_civil or split_part(v_chave, ' ', 1) = split_part(v_civil, ' ', 1) or (position(' ' in v_civil) > 0 and position(v_civil in v_chave) > 0)) then
      perform interno.erro('codinome_civil');
    end if;
  end if;
  if exists (select 1 from perfis o where o.id <> v and interno.rede_chave(o.rede_codinome) = v_chave)
     or exists (select 1 from papeis pa join perfis o on o.id = pa.usuario where o.id <> v and interno.rede_chave(o.nome) = v_chave) then
    perform interno.erro('codinome_usado');
  end if;
  update perfis set rede_codinome = v_nome, rede_codinome_ok = true where id = v;
  perform interno.registrar('rede_codinome', '', '{}'::jsonb);
  return jsonb_build_object('nome', v_nome, 'codinome_ok', true);
exception when unique_violation then perform interno.erro('codinome_usado');
end $$;

/** Publicar: post, resposta, repost com comentário, citação e chamado à ação. */
create or replace function public.rede_postar(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare
  v uuid := interno.eu(); x rede_posts; o rede_posts;
  v_texto text := btrim(coalesce(p ->> 'texto', ''));
  v_resposta uuid; v_repost uuid; v_cita jsonb; v_chamado jsonb; v_quando timestamptz;
  v_alcance text := coalesce(nullif(p ->> 'alcance', ''), 'publico');
  v_av jsonb; v_veredito text;
begin
  perform interno.aberta('comunidade');
  if not coalesce((select rede_16 from perfis where id = v), false) then perform interno.erro('confirme_idade'); end if;
  if not coalesce((select rede_codinome_ok and rede_codinome is not null from perfis where id = v), false) then perform interno.erro('confirme_codinome'); end if;
  if char_length(v_texto) > 500 then perform interno.erro('invalido:texto'); end if;
  if v_alcance not in ('publico', 'seguidores', 'equipe') then perform interno.erro('invalido:alcance'); end if;
  if v_alcance = 'equipe' and not interno.voluntario() then perform interno.erro('invalido:alcance'); end if;
  -- Contas com menos de uma semana publicam pouco: freia conta criada em massa para tumultuar.
  if (select criado_em from perfis where id = v) > now() - interval '7 days' then perform interno.limite('rede_post_novo', 8, 1440);
  else perform interno.limite('rede_post', 80, 1440); end if;
  -- Dado pessoal não vai para a rede: CPF, telefone e e-mail.
  if v_texto ~ '\d{3}\.?\d{3}\.?\d{3}-?\d{2}' or v_texto ~ '\(?\d{2}\)?\s?9\d{4}[-\s]?\d{4}' or v_texto ~* '[a-z0-9._%+-]+@[a-z0-9-]+\.[a-z.]{2,}' then
    perform interno.erro('dado_pessoal');
  end if;
  begin
    v_resposta := nullif(p ->> 'resposta_a', '')::uuid;
    v_repost := nullif(p ->> 'repost_de', '')::uuid;
  exception when others then perform interno.erro('invalido:post');
  end;
  if v_resposta is not null then
    select * into o from rede_posts where id = v_resposta;
    if not found or not interno.rede_ve(o) or o.oculto then perform interno.erro('nao_encontrado'); end if;
  end if;
  if v_repost is not null then
    select * into o from rede_posts where id = v_repost;
    if not found or o.oculto or o.alcance <> 'publico' or interno.rede_bloqueado(v, o.autor) then perform interno.erro('nao_encontrado'); end if;
  end if;
  if v_texto = '' and v_repost is null then perform interno.erro('invalido:texto'); end if;
  if not interno.rede_espaco_entra(nullif(btrim(coalesce(p ->> 'comunidade', '')), '')) then perform interno.erro('sem_permissao'); end if;
  if nullif(p ->> 'posicao', '') is not null and (v_resposta is null or p ->> 'posicao' not in ('favor', 'contra', 'sintese')) then perform interno.erro('invalido:posicao'); end if;
  if p ? 'cita' and jsonb_typeof(p -> 'cita') = 'object' then
    if coalesce(p -> 'cita' ->> 'tipo', '') not in ('aula', 'obra', 'materia') or coalesce(p -> 'cita' ->> 'caminho', '') !~ '^/(trilhas|acervo|jornal)/[a-z0-9/-]{2,200}$' then
      perform interno.erro('invalido:cita');
    end if;
    v_cita := jsonb_build_object('tipo', p -> 'cita' ->> 'tipo', 'caminho', p -> 'cita' ->> 'caminho', 'titulo', left(coalesce(p -> 'cita' ->> 'titulo', ''), 200));
  end if;
  if p ? 'chamado' and jsonb_typeof(p -> 'chamado') = 'object' then
    begin
      v_quando := (p -> 'chamado' ->> 'quando')::timestamptz;
    exception when others then perform interno.erro('invalido:chamado');
    end;
    if coalesce(p -> 'chamado' ->> 'tipo', '') not in ('ato', 'mutirao', 'assembleia', 'roda') or v_quando is null or v_quando < now() or v_quando > now() + interval '365 days'
       or char_length(coalesce(p -> 'chamado' ->> 'onde', '')) not between 3 and 160 then
      perform interno.erro('invalido:chamado');
    end if;
    v_chamado := jsonb_build_object('tipo', p -> 'chamado' ->> 'tipo', 'quando', v_quando, 'onde', btrim(p -> 'chamado' ->> 'onde'));
  end if;
  v_av := interno.veredito(v_texto || ' ' || coalesce(v_chamado ->> 'onde', ''), interno.cuida(), v);
  v_veredito := v_av ->> 'veredito';
  if v_veredito = 'publicar' and interno.aprovacao_manual() and not interno.cuida() then v_veredito := 'revisar'; v_av := jsonb_build_object('veredito', 'revisar', 'motivo', 'modo_seguranca'); end if;
  insert into rede_posts (autor, texto, comunidade, resposta_a, repost_de, cita, chamado, alcance, aviso, posicao, oculto, retido, avaliacao, motivo)
  values (v, v_texto, nullif(btrim(coalesce(p ->> 'comunidade', '')), ''), v_resposta, v_repost, v_cita, v_chamado, v_alcance, left(btrim(coalesce(p ->> 'aviso', '')), 80), nullif(p ->> 'posicao', ''),
          v_veredito <> 'publicar', v_veredito = 'revisar', case v_veredito when 'publicar' then 'publicada' when 'bloquear' then 'bloqueada' else 'revisao' end, coalesce(v_av ->> 'motivo', ''))
  returning * into x;
  if v_resposta is not null and o.autor is distinct from v and x.oculto = false then
    perform interno.avisar_em(o.autor, format('%s respondeu ao seu post na Rede Lúcia: “%s”', interno.rede_nome(v), left(v_texto, 120)), 'rede');
  end if;
  return interno.rede_post_json(x);
exception when check_violation then perform interno.erro('invalido:post');
end $$;

/** A linha do tempo, em ordem de tempo (40 por vez): de todos, de quem sigo, de uma comunidade, de um perfil ou os chamados. */
create or replace function public.rede_linha(p_modo text default 'tudo', p_comunidade text default null, p_usuario uuid default null, p_antes timestamptz default null) returns jsonb
language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  if p_modo = 'perfil' and p_usuario is not null and p_usuario is distinct from auth.uid() and coalesce((select rede_invisivel from perfis where id = p_usuario), false) then
    return '[]'::jsonb;
  end if;
  return coalesce((select jsonb_agg(interno.rede_post_json(x) order by case when p_modo = 'chamados' then (x.chamado ->> 'quando')::timestamptz end, x.criado_em desc) from (
    select p.* from rede_posts p
    where interno.rede_ve(p) and (p_antes is null or p.criado_em < p_antes)
      and case p_modo
        when 'seguindo' then p.resposta_a is null and (p.autor = auth.uid() or exists (select 1 from rede_seguindo s where s.quem = auth.uid() and s.segue = p.autor))
        when 'comunidade' then p.resposta_a is null and p.comunidade = p_comunidade
        when 'minhas' then p.resposta_a is null and (p.comunidade in (select c.comunidade from rede_comunidades_seguidas c where c.usuario = auth.uid())
                                                      or p.comunidade in (select m.espaco from rede_espaco_membros m where m.usuario = auth.uid()))
        when 'perfil' then p.autor = p_usuario
        when 'chamados' then p.chamado is not null and (p.chamado ->> 'quando')::timestamptz > now() - interval '6 hours'
        else p.resposta_a is null end
    order by p.criado_em desc limit 40) x), '[]'::jsonb);
end $$;

/** Um post e o fio das respostas. */
create or replace function public.rede_post_ver(p_id uuid) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare x rede_posts;
begin
  select * into x from rede_posts where id = p_id;
  if not found or not interno.rede_ve(x) then perform interno.erro('nao_encontrado'); end if;
  return jsonb_build_object('post', interno.rede_post_json(x),
    'respostas', (select coalesce(jsonb_agg(interno.rede_post_json(r) order by r.criado_em), '[]'::jsonb) from rede_posts r where r.resposta_a = x.id and interno.rede_ve(r)));
end $$;

/** Quantos posts novos chegaram desde a última olhada (o aviso "N posts novos", sem recarregar a lista sozinho). */
create or replace function public.rede_novos(p_desde timestamptz) returns integer language sql stable security definer set search_path = interno, pg_temp as $$
  select count(*)::int from rede_posts p where p.criado_em > p_desde and p.resposta_a is null and interno.rede_ve(p) and p.autor is distinct from auth.uid()
$$;

create or replace function public.rede_apagar(p_id uuid) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  delete from rede_posts where id = p_id and autor = interno.eu();
  if not found then perform interno.erro('nao_encontrado'); end if;
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.rede_apoiar(p_id uuid, p_sim boolean) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); x rede_posts;
begin
  select * into x from rede_posts where id = p_id;
  if not found or not interno.rede_ve(x) then perform interno.erro('nao_encontrado'); end if;
  if coalesce(p_sim, true) then insert into rede_apoios (post, usuario) values (p_id, v) on conflict do nothing;
  else delete from rede_apoios where post = p_id and usuario = v; end if;
  return jsonb_build_object('ok', true);
end $$;

/** "Eu vou" num chamado (ato, mutirão, assembleia). */
create or replace function public.rede_vou(p_id uuid, p_sim boolean) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); x rede_posts;
begin
  select * into x from rede_posts where id = p_id;
  if not found or x.chamado is null or not interno.rede_ve(x) then perform interno.erro('nao_encontrado'); end if;
  if coalesce(p_sim, true) then insert into rede_vou (post, usuario) values (p_id, v) on conflict do nothing;
  else delete from rede_vou where post = p_id and usuario = v; end if;
  return jsonb_build_object('ok', true, 'vou', (select count(*) from rede_vou where post = p_id));
end $$;

create or replace function public.rede_seguir(p_usuario uuid, p_sim boolean) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if p_usuario is null or p_usuario = v or not exists (select 1 from perfis where id = p_usuario) or interno.rede_bloqueado(v, p_usuario) then perform interno.erro('invalido:usuario'); end if;
  if coalesce(p_sim, true) then
    perform interno.limite('rede_seguir', 200, 1440);
    insert into rede_seguindo (quem, segue) values (v, p_usuario) on conflict do nothing;
  else delete from rede_seguindo where quem = v and segue = p_usuario; end if;
  return jsonb_build_object('ok', true);
end $$;

/** Bloquear: some da linha dos dois, desfaz o seguir nos dois sentidos e ninguém responde a ninguém. */
create or replace function public.rede_bloquear(p_usuario uuid, p_sim boolean) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if p_usuario is null or p_usuario = v then perform interno.erro('invalido:usuario'); end if;
  if coalesce(p_sim, true) then
    insert into rede_bloqueios (quem, bloqueado) values (v, p_usuario) on conflict do nothing;
    delete from rede_seguindo where (quem = v and segue = p_usuario) or (quem = p_usuario and segue = v);
  else delete from rede_bloqueios where quem = v and bloqueado = p_usuario; end if;
  return jsonb_build_object('ok', true);
end $$;

/** O perfil na rede: sem número de seguidores; diz só se a pessoa segue você e se você segue. Perfil invisível não abre. */
create or replace function public.rede_perfil(p_usuario uuid) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare f perfis;
begin
  select * into f from perfis where id = p_usuario;
  if not found then perform interno.erro('nao_encontrado'); end if;
  if f.rede_invisivel and f.id is distinct from auth.uid() then return jsonb_build_object('invisivel', true, 'nome', interno.rede_nome(f.id), 'codinome', true); end if;
  return jsonb_build_object('id', f.id, 'nome', interno.rede_nome(f.id), 'codinome', true, 'avatar', null, 'bio', f.rede_bio, 'invisivel', false,
    'equipe', interno.voluntario_e(f.id),
    'sigo', exists (select 1 from rede_seguindo where quem = auth.uid() and segue = f.id),
    'me_segue', exists (select 1 from rede_seguindo where quem = f.id and segue = auth.uid()),
    'bloqueei', exists (select 1 from rede_bloqueios where quem = auth.uid() and bloqueado = f.id),
    'eu', f.id = auth.uid());
end $$;

/** O registro público de moderação: quantos posts e mensagens a mediação ocultou e quantas contas baniu, por semana. Sem nomes. */
create or replace function public.rede_moderacao_publica() returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select coalesce(jsonb_agg(jsonb_build_object('semana', s.semana, 'ocultados', s.ocultados, 'banimentos', s.banimentos) order by s.semana desc), '[]'::jsonb)
  from (select date_trunc('week', criado_em)::date as semana,
               count(*) filter (where acao = 'comunidade_ocultar')::int as ocultados,
               count(*) filter (where acao = 'mediacao_banir')::int as banimentos
        from auditoria where acao in ('comunidade_ocultar', 'mediacao_banir') and criado_em > now() - interval '120 days'
        group by 1) s
$$;

do $$
declare f record;
begin
  for f in select p.oid::regprocedure as assinatura from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname in ('rede_confirmar_idade', 'rede_config', 'rede_eu', 'rede_postar', 'rede_linha', 'rede_post_ver', 'rede_novos', 'rede_apagar',
             'rede_apoiar', 'rede_vou', 'rede_seguir', 'rede_bloquear', 'rede_perfil', 'rede_moderacao_publica') loop
    execute format('revoke all on function %s from public', f.assinatura);
    execute format('grant execute on function %s to anon, authenticated, service_role', f.assinatura);
  end loop;
end $$;

-- ───────────────────────────── Rede Lúcia, segunda parte ─────────────────────────────
-- Espaços fechados (organização que não pode ficar aberta: entra só com convite de quem cuida do espaço, contra
-- infiltração), comunidades que a pessoa segue (a linha "Minhas comunidades"), moderadores por comunidade, a posição
-- nos fios de debate (a favor, contra, síntese), a busca nos posts com hashtags, o aviso de menção e a portabilidade
-- (baixar tudo o que a pessoa escreveu).

alter table interno.rede_posts add column if not exists posicao text check (posicao is null or posicao in ('favor', 'contra', 'sintese'));

create table if not exists interno.rede_espacos (
  slug text primary key check (slug ~ '^fechado-[a-z0-9-]{2,50}$'),
  nome text not null check (char_length(nome) between 3 and 60),
  descricao text not null default '' check (char_length(descricao) <= 300),
  criado_por uuid references interno.perfis (id) on delete set null,
  codigo text not null check (codigo ~ '^[A-Za-z0-9]{12}$'),
  criado_em timestamptz not null default now()
);
create table if not exists interno.rede_espaco_membros (
  espaco text not null references interno.rede_espacos (slug) on delete cascade,
  usuario uuid not null references interno.perfis (id) on delete cascade,
  cuida boolean not null default false,
  entrou_em timestamptz not null default now(),
  primary key (espaco, usuario)
);
create table if not exists interno.rede_comunidades_seguidas (
  usuario uuid not null references interno.perfis (id) on delete cascade,
  comunidade text not null check (comunidade ~ '^[a-z0-9-]{2,60}$'),
  primary key (usuario, comunidade)
);
create table if not exists interno.rede_moderadores (
  comunidade text not null check (comunidade ~ '^[a-z0-9-]{2,60}$'),
  usuario uuid not null references interno.perfis (id) on delete cascade,
  primary key (comunidade, usuario)
);
revoke all on interno.rede_espacos, interno.rede_espaco_membros, interno.rede_comunidades_seguidas, interno.rede_moderadores from public;

/** Espaço fechado: só quem é membro vê e escreve. As outras comunidades são abertas. */
create or replace function interno.rede_espaco_entra(p_comunidade text) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select p_comunidade is null or p_comunidade not like 'fechado-%'
    or exists (select 1 from rede_espaco_membros m where m.espaco = p_comunidade and m.usuario = auth.uid())
$$;

-- A regra de quem vê um post passa a conferir também o espaço fechado.
create or replace function interno.rede_ve(p interno.rede_posts) returns boolean language sql stable security definer set search_path = interno, pg_temp as $$
  select (not p.oculto or p.autor = auth.uid())
    and not interno.rede_bloqueado(auth.uid(), p.autor)
    and interno.rede_espaco_entra(p.comunidade)
    and (p.alcance = 'publico' or p.autor = auth.uid()
         or (p.alcance = 'seguidores' and exists (select 1 from rede_seguindo s where s.quem = auth.uid() and s.segue = p.autor))
         or (p.alcance = 'equipe' and interno.voluntario()))
$$;

/** Abrir um espaço fechado: só a equipe abre (quem abre cuida dele e convida). */
create or replace function public.rede_espaco_criar(p_nome text, p_descricao text default '') returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_nome text := interno.txt(p_nome, 'nome', 3, 60); v_slug text; v_codigo text;
begin
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  perform interno.limite('rede_espaco', 5, 1440);
  v_slug := 'fechado-' || left(trim(both '-' from regexp_replace(lower(translate(v_nome, 'áàâãäéèêëíìîïóòôõöúùûüçñ', 'aaaaaeeeeiiiiooooouuuucn')), '[^a-z0-9]+', '-', 'g')), 40) || '-' || substr(md5(random()::text), 1, 4);
  v_codigo := substr(md5(random()::text || clock_timestamp()::text), 1, 12);
  insert into rede_espacos (slug, nome, descricao, criado_por, codigo) values (v_slug, v_nome, interno.txt(coalesce(p_descricao, ''), 'descricao', 0, 300), v, v_codigo);
  insert into rede_espaco_membros (espaco, usuario, cuida) values (v_slug, v, true);
  return jsonb_build_object('slug', v_slug, 'codigo', v_codigo);
end $$;

/** Entrar num espaço fechado pelo código do convite. */
create or replace function public.rede_espaco_entrar(p_codigo text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); e rede_espacos;
begin
  perform interno.limite('rede_espaco_entrar', 20, 60);
  select * into e from rede_espacos where codigo = p_codigo;
  if not found then perform interno.erro('convite_vencido'); end if;
  insert into rede_espaco_membros (espaco, usuario) values (e.slug, v) on conflict do nothing;
  return jsonb_build_object('slug', e.slug, 'nome', e.nome);
end $$;

/** Quem cuida troca o código (o convite antigo deixa de valer) ou tira alguém. */
create or replace function public.rede_espaco_cuidar(p_slug text, p_acao text, p_usuario uuid default null) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_codigo text;
begin
  if not exists (select 1 from rede_espaco_membros where espaco = p_slug and usuario = v and cuida) and not interno.cuida() then perform interno.erro('sem_permissao'); end if;
  if p_acao = 'novo_codigo' then
    v_codigo := substr(md5(random()::text || clock_timestamp()::text), 1, 12);
    update rede_espacos set codigo = v_codigo where slug = p_slug;
    return jsonb_build_object('codigo', v_codigo);
  elsif p_acao = 'tirar' and p_usuario is not null and p_usuario <> v then
    delete from rede_espaco_membros where espaco = p_slug and usuario = p_usuario;
    return jsonb_build_object('ok', true);
  end if;
  perform interno.erro('invalido:acao');
end $$;

/** Os espaços fechados de que a pessoa faz parte (com o código, para quem cuida). */
create or replace function public.rede_meus_espacos() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  return (select coalesce(jsonb_agg(jsonb_build_object('slug', e.slug, 'nome', e.nome, 'descricao', e.descricao, 'cuido', m.cuida, 'codigo', case when m.cuida then e.codigo end,
            'membros', (select count(*) from rede_espaco_membros x where x.espaco = e.slug)) order by e.nome), '[]'::jsonb)
          from rede_espaco_membros m join rede_espacos e on e.slug = m.espaco where m.usuario = v);
end $$;

create or replace function public.rede_comunidade_seguir(p_comunidade text, p_sim boolean) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu();
begin
  if coalesce(p_comunidade, '') !~ '^[a-z0-9-]{2,60}$' or p_comunidade like 'fechado-%' then perform interno.erro('invalido:comunidade'); end if;
  if coalesce(p_sim, true) then insert into rede_comunidades_seguidas (usuario, comunidade) values (v, p_comunidade) on conflict do nothing;
  else delete from rede_comunidades_seguidas where usuario = v and comunidade = p_comunidade; end if;
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.rede_comunidades_minhas() returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select coalesce(jsonb_agg(comunidade order by comunidade), '[]'::jsonb) from rede_comunidades_seguidas where usuario = auth.uid()
$$;

/** Moderadores por comunidade: a mediação nomeia; quem modera oculta posts daquela comunidade. */
create or replace function public.rede_moderador_definir(p_comunidade text, p_usuario uuid, p_sim boolean) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.cuida() then perform interno.erro('sem_permissao'); end if;
  if coalesce(p_sim, true) then insert into rede_moderadores (comunidade, usuario) values (p_comunidade, p_usuario) on conflict do nothing;
  else delete from rede_moderadores where comunidade = p_comunidade and usuario = p_usuario; end if;
  perform interno.registrar('rede_moderador', p_comunidade, jsonb_build_object('usuario', p_usuario, 'sim', coalesce(p_sim, true)));
  return jsonb_build_object('ok', true);
end $$;

create or replace function public.rede_moderar(p_id uuid, p_ocultar boolean) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); x rede_posts;
begin
  select * into x from rede_posts where id = p_id;
  if not found then perform interno.erro('nao_encontrado'); end if;
  if not (interno.cuida() or exists (select 1 from rede_moderadores where comunidade = x.comunidade and usuario = v)
          or (x.comunidade like 'fechado-%' and exists (select 1 from rede_espaco_membros where espaco = x.comunidade and usuario = v and cuida))) then
    perform interno.erro('sem_permissao');
  end if;
  update rede_posts set oculto = coalesce(p_ocultar, true), retido = false where id = p_id;
  perform interno.registrar(case when coalesce(p_ocultar, true) then 'comunidade_ocultar' else 'comunidade_mostrar' end, p_id::text, jsonb_build_object('tipo', 'post', 'por', 'moderador'));
  if coalesce(p_ocultar, true) then perform interno.avisar_em(x.autor, 'Um post seu na Rede Lúcia foi ocultado pela moderação da comunidade. Releia as regras; se achar que houve engano, use a página Denunciar.', 'rede'); end if;
  return jsonb_build_object('ok', true);
end $$;

/** Busca nos posts (texto e #hashtags), respeitando quem pode ver. */
create or replace function public.rede_buscar(p_termo text) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v_termo text := btrim(left(coalesce(p_termo, ''), 80));
begin
  if char_length(v_termo) < 2 then return '[]'::jsonb; end if;
  perform interno.limite('rede_buscar', 120, 60);
  return coalesce((select jsonb_agg(interno.rede_post_json(x) order by x.criado_em desc) from (
    select p.* from rede_posts p where interno.rede_ve(p) and position(lower(v_termo) in lower(p.texto)) > 0 order by p.criado_em desc limit 40) x), '[]'::jsonb);
end $$;

/** Portabilidade: tudo o que a pessoa escreveu na rede, para baixar. */
create or replace function public.rede_meus_posts() returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select coalesce(jsonb_agg(jsonb_build_object('id', id, 'texto', texto, 'comunidade', comunidade, 'criado_em', criado_em, 'resposta_a', resposta_a, 'repost_de', repost_de,
           'cita', cita, 'chamado', chamado, 'alcance', alcance, 'aviso', aviso, 'posicao', posicao) order by criado_em), '[]'::jsonb)
  from rede_posts where autor = auth.uid()
$$;

do $$
declare f record;
begin
  for f in select p.oid::regprocedure as assinatura from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname in ('rede_espaco_criar', 'rede_espaco_entrar', 'rede_espaco_cuidar', 'rede_meus_espacos', 'rede_comunidade_seguir', 'rede_comunidades_minhas',
             'rede_moderador_definir', 'rede_moderar', 'rede_buscar', 'rede_meus_posts') loop
    execute format('revoke all on function %s from public', f.assinatura);
    execute format('grant execute on function %s to anon, authenticated, service_role', f.assinatura);
  end loop;
end $$;

-- ───────────────────────────── Canais no celular ─────────────────────────────
-- Os endereços públicos do canal do WhatsApp e do grupo/canal do Telegram do instituto, mostrados na página "Receba no
-- seu celular". Quem cria os canais é a coordenação, fora do site; aqui só fica o endereço.

create or replace function public.canais() returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select jsonb_build_object('whatsapp', coalesce(valor ->> 'whatsapp', ''), 'telegram', coalesce(valor ->> 'telegram', ''))
  from (select coalesce((select valor from configuracoes where chave = 'canais'), '{}'::jsonb) as valor) c
$$;

create or replace function public.canais_salvar(p jsonb) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_whats text := btrim(coalesce(p ->> 'whatsapp', '')); v_tele text := btrim(coalesce(p ->> 'telegram', '')); v jsonb;
begin
  perform interno.eu();
  if not interno.coord() then perform interno.erro('sem_permissao'); end if;
  if v_whats <> '' and v_whats !~ '^https://(www\.)?(whatsapp\.com/channel/|chat\.whatsapp\.com/)[A-Za-z0-9]{10,60}$' then perform interno.erro('invalido:whatsapp'); end if;
  if v_tele <> '' and v_tele !~ '^https://t\.me/\+?[A-Za-z0-9_]{3,64}$' then perform interno.erro('invalido:telegram'); end if;
  v := jsonb_build_object('whatsapp', v_whats, 'telegram', v_tele);
  insert into configuracoes (chave, valor) values ('canais', v) on conflict (chave) do update set valor = excluded.valor;
  perform interno.registrar('canais_configurados', '', v);
  return v;
end $$;

do $$
declare f record;
begin
  for f in select p.oid::regprocedure as assinatura from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname in ('canais', 'canais_salvar') loop
    execute format('revoke all on function %s from public', f.assinatura);
    execute format('grant execute on function %s to anon, authenticated, service_role', f.assinatura);
  end loop;
end $$;

-- ───────────────────────────── Mapa público dos núcleos ─────────────────────────────
/** Os núcleos que a coordenação pôs no mapa público: cidade, estado, como se encontram e o contato do próprio núcleo. */
create or replace function public.nucleos_publicos() returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  select coalesce(jsonb_agg(jsonb_build_object('nome', nome, 'cidade', cidade, 'uf', uf, 'tipo', tipo, 'encontros', encontros, 'ponto', ponto, 'contato', contato)
           order by uf, cidade, nome), '[]'::jsonb)
  from nucleos where ativo and publico
$$;
revoke all on function public.nucleos_publicos() from public;
grant execute on function public.nucleos_publicos() to anon, authenticated, service_role;

revoke all on function public.denunciar(text, text, text, text, boolean) from public;
grant execute on function public.denunciar(text, text, text, text, boolean) to anon, authenticated, service_role;

-- ───────────────────────────── Fila de aulas a escrever ─────────────────────────────
-- Cada aula prevista no roteiro de uma trilha (content/trilhas/<trilha>/plano.json) vira uma tarefa que alguém da equipe
-- reserva: "eu escrevo esta". A reserva tem prazo sugerido de 14 dias; vencida há uma semana, outra pessoa pode pegar.
-- Pronta, vai para a revisão por pares: outra pessoa da equipe revisa antes de ir para a fila de revisão de sempre.

create table if not exists interno.aulas_reservas (
  trilha text not null check (trilha ~ '^[a-z0-9-]{2,80}$'),
  aula text not null check (aula ~ '^[a-z0-9-]{2,120}$'),
  titulo text not null default '' check (char_length(titulo) <= 200),
  usuario uuid not null references interno.perfis (id) on delete cascade,
  revisor uuid references interno.perfis (id) on delete set null,
  situacao text not null default 'escrevendo' check (situacao in ('escrevendo', 'revisao', 'feita')),
  reservada_em timestamptz not null default now(),
  prazo date not null default ((now() + interval '14 days')::date),
  primary key (trilha, aula)
);
revoke all on interno.aulas_reservas from public;

create or replace function public.aulas_reservas_listar() returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  return (select coalesce(jsonb_agg(jsonb_build_object('trilha', r.trilha, 'aula', r.aula, 'titulo', r.titulo, 'situacao', r.situacao, 'prazo', r.prazo,
            'quem', coalesce((select interno.nome_visto(nome) from perfis where id = r.usuario), ''), 'minha', r.usuario = auth.uid(),
            'revisor', coalesce((select interno.nome_visto(nome) from perfis where id = r.revisor), ''), 'reviso', r.revisor = auth.uid(),
            'vencida', r.situacao = 'escrevendo' and r.prazo < current_date)), '[]'::jsonb) from aulas_reservas r);
end $$;

/** "Eu escrevo esta": no máximo três aulas sendo escritas por pessoa; a de outra pessoa só se o prazo venceu há uma semana. */
create or replace function public.aula_reservar(p_trilha text, p_aula text, p_titulo text default '') returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); r aulas_reservas;
begin
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  if (select count(*) from aulas_reservas where usuario = v and situacao = 'escrevendo') >= 3 then perform interno.erro('limite:tres_aulas'); end if;
  select * into r from aulas_reservas where trilha = p_trilha and aula = p_aula for update;
  if found then
    if r.usuario = v then return jsonb_build_object('ok', true); end if;
    if not (r.situacao = 'escrevendo' and r.prazo < current_date - 7) then perform interno.erro('reservada'); end if;
    perform interno.avisar(r.usuario, 'A aula "' || left(r.titulo, 120) || '" passou do prazo e outra pessoa da equipe pegou para escrever. Se já tinha um rascunho, combine com ela nas Conversas.');
    delete from aulas_reservas where trilha = p_trilha and aula = p_aula;
  end if;
  insert into aulas_reservas (trilha, aula, titulo, usuario) values (p_trilha, p_aula, interno.txt(coalesce(p_titulo, ''), 'titulo', 0, 200), v);
  perform interno.registrar('aula_reservada', p_trilha || '/' || p_aula);
  return jsonb_build_object('ok', true);
exception when check_violation then perform interno.erro('invalido:aula');
end $$;

/** Liberar (quem reservou ou a coordenação), pedir revisão, revisar (outra pessoa), concluir (quem revisa) e mais prazo. */
create or replace function public.aula_reserva_mudar(p_trilha text, p_aula text, p_acao text) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); r aulas_reservas;
begin
  if not interno.voluntario() then perform interno.erro('sem_permissao'); end if;
  select * into r from aulas_reservas where trilha = p_trilha and aula = p_aula for update;
  if not found then perform interno.erro('nao_encontrado'); end if;
  if p_acao = 'liberar' then
    if r.usuario <> v and not (interno.coord() or interno.tem('vice')) then perform interno.erro('sem_permissao'); end if;
    delete from aulas_reservas where trilha = p_trilha and aula = p_aula;
  elsif p_acao = 'revisao' then
    if r.usuario <> v then perform interno.erro('sem_permissao'); end if;
    update aulas_reservas set situacao = 'revisao', revisor = null where trilha = p_trilha and aula = p_aula;
  elsif p_acao = 'revisar' then
    if r.usuario = v or r.situacao <> 'revisao' then perform interno.erro('sem_permissao'); end if;
    update aulas_reservas set revisor = v where trilha = p_trilha and aula = p_aula;
    perform interno.avisar(r.usuario, interno.nome_visto((select nome from perfis where id = v)) || ' vai revisar a sua aula "' || left(r.titulo, 120) || '".');
  elsif p_acao = 'feita' then
    if not (r.revisor = v or interno.coord()) then perform interno.erro('sem_permissao'); end if;
    update aulas_reservas set situacao = 'feita' where trilha = p_trilha and aula = p_aula;
    perform interno.avisar(r.usuario, 'A revisão por pares da sua aula "' || left(r.titulo, 120) || '" terminou. Agora é enviar pelo Escrever para a fila de revisão.');
  elsif p_acao = 'prazo' then
    if r.usuario <> v then perform interno.erro('sem_permissao'); end if;
    update aulas_reservas set prazo = greatest(prazo, current_date) + 7 where trilha = p_trilha and aula = p_aula;
  else
    perform interno.erro('invalido:acao');
  end if;
  perform interno.registrar('aula_reserva_' || p_acao, p_trilha || '/' || p_aula);
  return jsonb_build_object('ok', true);
end $$;

do $$
declare f record;
begin
  for f in select p.oid::regprocedure as assinatura from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname in ('aulas_reservas_listar', 'aula_reservar', 'aula_reserva_mudar') loop
    execute format('revoke all on function %s from public', f.assinatura);
    execute format('grant execute on function %s to anon, authenticated, service_role', f.assinatura);
  end loop;
end $$;

-- ───────────────────────────── Voluntário sumido ─────────────────────────────
-- Uma vez por dia, a coordenação e a vice recebem um aviso com quem da equipe não aparece há mais de 30 dias (sem contar
-- quem marcou férias). Cada pessoa entra no aviso uma vez só por sumiço; quando ela volta a entrar, sai da lista e pode
-- entrar de novo num sumiço futuro. O aviso é para cuidar (perguntar se está tudo bem), não para cobrar.

create table if not exists interno.sumidos_avisados (
  usuario uuid primary key references interno.perfis (id) on delete cascade,
  avisado_em timestamptz not null default now()
);
revoke all on interno.sumidos_avisados from public;

create or replace function interno.avisar_sumidos() returns integer language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_nomes text; v_n integer;
begin
  -- Quem voltou depois do aviso sai da lista.
  delete from sumidos_avisados a using perfis f where f.id = a.usuario and f.visto_em > a.avisado_em;
  with novos as (
    select f.id, interno.nome_visto(f.nome) as nome from perfis f
    where not f.suspenso and f.visto_em < now() - interval '30 days'
      and (f.ferias_ate is null or f.ferias_ate < current_date)
      and exists (select 1 from papeis p where p.usuario = f.id)
      and not exists (select 1 from sumidos_avisados a where a.usuario = f.id)
    order by f.visto_em limit 50
  ), marcados as (
    insert into sumidos_avisados (usuario) select id from novos returning usuario
  )
  select count(*), string_agg(n.nome, ', ' order by n.nome) into v_n, v_nomes from novos n;
  if v_n > 0 then
    perform interno.avisar_lideranca('Sem aparecer no painel há mais de 30 dias: ' || v_nomes || '. Que tal mandar uma mensagem perguntando se está tudo bem? (Voluntários e convites › Sumidas)');
  end if;
  return v_n;
end $$;
revoke all on function interno.avisar_sumidos() from public, anon, authenticated;

do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.schedule('lucia-sumidos', '0 12 * * *', 'select interno.avisar_sumidos()');
  end if;
exception when others then null;
end $$;

-- ───────────────────────────── Turma do mês ─────────────────────────────
-- Todo mês uma trilha começa no dia 1, para estudar junto em quatro semanas, com um encontro por semana na sala de
-- vídeo (lib/turma-do-mes.ts escolhe a trilha). Aqui fica só quem entrou na turma: o progresso de cada aula continua
-- no aparelho de cada um, como em todo o site.
create table if not exists interno.turmas_mes (
  mes text not null check (mes ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  usuario uuid not null references interno.perfis (id) on delete cascade,
  criado_em timestamptz not null default now(),
  primary key (mes, usuario)
);
revoke all on interno.turmas_mes from public;

-- A sala do encontro de cada mês: um nome sorteado na primeira inscrição, que só quem está na turma recebe.
create table if not exists interno.turmas_salas (
  mes text primary key check (mes ~ '^[0-9]{4}-(0[1-9]|1[0-2])$'),
  sala text not null check (sala ~ '^InstitutoLucia-Turma-[A-Za-z0-9-]{8,60}$')
);
revoke all on interno.turmas_salas from public;

/** Quantas pessoas estão na turma do mês e se quem pergunta está nela (sem sessão, `eu` é falso). A sala vai só para quem entrou. */
create or replace function public.turma_mes(p_mes text) returns jsonb language sql stable security definer set search_path = interno, pg_temp as $$
  with eu as (select auth.uid() is not null and exists (select 1 from turmas_mes where mes = p_mes and usuario = auth.uid()) as dentro)
  select jsonb_build_object(
    'inscritos', (select count(*) from turmas_mes where mes = p_mes),
    'eu', (select dentro from eu),
    'sala', case when (select dentro from eu) then (select sala from turmas_salas where mes = p_mes) end)
$$;

/** Entrar (p_entrar verdadeiro) ou sair da turma. Só a turma deste mês ou a do próximo. */
create or replace function public.turma_mes_entrar(p_mes text, p_entrar boolean default true) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); v_agora text := to_char(now() at time zone 'America/Sao_Paulo', 'YYYY-MM');
        v_prox text := to_char((now() at time zone 'America/Sao_Paulo') + interval '1 month', 'YYYY-MM');
begin
  if p_mes is null or p_mes not in (v_agora, v_prox) then perform interno.erro('invalido:mes'); end if;
  if coalesce(p_entrar, true) then
    insert into turmas_mes (mes, usuario) values (p_mes, v) on conflict do nothing;
    insert into turmas_salas (mes, sala) values (p_mes, 'InstitutoLucia-Turma-' || p_mes || '-' || substr(md5(gen_random_uuid()::text), 1, 12)) on conflict do nothing;
  else
    delete from turmas_mes where mes = p_mes and usuario = v;
  end if;
  return public.turma_mes(p_mes);
end $$;

do $$
declare f record;
begin
  for f in select p.oid::regprocedure as assinatura from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname in ('turma_mes', 'turma_mes_entrar') loop
    execute format('revoke all on function %s from public', f.assinatura);
    execute format('grant execute on function %s to anon, authenticated, service_role', f.assinatura);
  end loop;
end $$;

-- ───────────────────────────── Relatório trimestral ─────────────────────────────
-- O que o instituto fez em cada trimestre, em números que qualquer pessoa pode conferir: contas novas, voluntários
-- que entraram, contribuições publicadas, tarefas feitas, núcleos criados, posts na Comunidade, certificados e o
-- dinheiro (só dos meses com relatório de contas publicado). Contagens, nunca nomes. A página /relatorio junta isso
-- com o que sai do próprio conteúdo (aulas publicadas no trimestre, pelo histórico do repositório).
create or replace function public.relatorio_trimestral(p_ano int, p_tri int) returns jsonb language plpgsql stable security definer set search_path = interno, pg_temp as $$
declare v_ini timestamptz; v_fim timestamptz; v_mes_ini date; v_mes_fim date;
begin
  if p_ano is null or p_ano < 2024 or p_ano > 2100 or p_tri is null or p_tri not between 1 and 4 then perform interno.erro('invalido:trimestre'); end if;
  v_mes_ini := make_date(p_ano, (p_tri - 1) * 3 + 1, 1);
  v_mes_fim := (v_mes_ini + interval '3 months')::date;
  v_ini := v_mes_ini::timestamp at time zone 'America/Sao_Paulo';
  v_fim := v_mes_fim::timestamp at time zone 'America/Sao_Paulo';
  return jsonb_build_object(
    'ano', p_ano, 'tri', p_tri,
    'contas', (select count(*) from perfis where criado_em >= v_ini and criado_em < v_fim),
    'voluntarios', (select count(*) from inscricoes where status = 'aceita' and decidido_em >= v_ini and decidido_em < v_fim),
    'contribuicoes', (select count(*) from contribuicoes where status in ('publicada', 'aprovada', 'resolvida') and coalesce(publicado_em, revisado_em) >= v_ini and coalesce(publicado_em, revisado_em) < v_fim),
    'tarefas', (select count(*) from tarefas where status in ('aprovada', 'concluida') and coalesce(revisada_em, entregue_em) >= v_ini and coalesce(revisada_em, entregue_em) < v_fim),
    'nucleos', (select count(*) from nucleos where criado_em >= v_ini and criado_em < v_fim),
    'nucleos_ativos', (select count(*) from nucleos where ativo and criado_em < v_fim),
    'posts', (select count(*) from rede_posts where not oculto and criado_em >= v_ini and criado_em < v_fim),
    'certificados', (select count(*) from certificados_alunos where emitido_em >= v_ini and emitido_em < v_fim),
    'turma', (select count(*) from turmas_mes where mes in (to_char(v_mes_ini, 'YYYY-MM'), to_char(v_mes_ini + interval '1 month', 'YYYY-MM'), to_char(v_mes_ini + interval '2 months', 'YYYY-MM'))),
    'contas_meses', (select count(*) from apoio_relatorios where status = 'publicado' and mes >= v_mes_ini and mes < v_mes_fim),
    'entradas', (select coalesce(sum((dados ->> 'total_entradas')::numeric), 0) from apoio_relatorios where status = 'publicado' and mes >= v_mes_ini and mes < v_mes_fim),
    'saidas', (select coalesce(sum((dados ->> 'total_saidas')::numeric), 0) from apoio_relatorios where status = 'publicado' and mes >= v_mes_ini and mes < v_mes_fim));
end $$;
revoke all on function public.relatorio_trimestral(int, int) from public;
grant execute on function public.relatorio_trimestral(int, int) to anon, authenticated, service_role;

-- ───────────────────────────── Chamadas nos canais ─────────────────────────────
-- Como no Discord: qualquer pessoa de uma conversa (canal de departamento, grupo ou privada) começa uma chamada de voz
-- ou de vídeo ali mesmo, e todo mundo da conversa é avisado para entrar. É uma reunião ao vivo ligada à conversa, com
-- sala sorteada que só quem está na conversa recebe; acaba sozinha quando a última pessoa sai (ou some sem sair).

/** Encerra as chamadas de canal sem ninguém: quem fechou a aba sem sair para de contar depois de 90 segundos. */
create or replace function interno.chamadas_limpar() returns void language plpgsql security definer set search_path = interno, pg_temp as $$
declare r reunioes;
begin
  for r in select * from reunioes x where x.conversa is not null and x.status = 'ao_vivo' and coalesce(x.iniciada_em, x.inicio) < now() - interval '2 minutes'
             and not exists (select 1 from reunioes_presencas p where p.reuniao = x.id and p.saiu_em is null and p.visto_em > now() - interval '90 seconds') loop
    update reunioes set status = 'encerrada', encerrada_em = now() where id = r.id;
    update reunioes_presencas set saiu_em = coalesce(saiu_em, visto_em) where reuniao = r.id and saiu_em is null;
  end loop;
end $$;

/** Começar uma chamada na conversa (ou devolver a que já está acontecendo nela) e avisar todo mundo da conversa. */
create or replace function public.chat_chamada_iniciar(p_conversa uuid, p_video boolean default false) returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
declare v uuid := interno.eu(); r reunioes; c conversas; v_nome text; v_quem text;
begin
  if not interno.na_conversa(p_conversa) then perform interno.erro('sem_permissao'); end if;
  perform interno.chamadas_limpar();
  select * into r from reunioes where conversa = p_conversa and status = 'ao_vivo' order by iniciada_em desc limit 1;
  if found then return interno.reuniao_json(r); end if;
  select * into c from conversas where id = p_conversa;
  v_quem := coalesce((select interno.primeiro_nome(nome) from perfis where id = v), 'Alguém');
  v_nome := case when c.tipo = 'direta' then 'Chamada com ' || v_quem else 'Chamada em #' || coalesce(nullif(c.nome, ''), 'canal') end;
  insert into reunioes (titulo, inicio, duracao, tipo, status, iniciada_em, organizador, conversa, video)
  values (left(v_nome, 140), now(), 60, 'convidados', 'ao_vivo', now(), v, p_conversa, coalesce(p_video, false))
  returning * into r;
  -- O sino de todo mundo da conversa (menos quem começou), e o aviso dentro da própria conversa.
  insert into avisos (para, texto)
  select m.usuario, left(v_quem || ' começou uma chamada ' || case when r.video then 'de vídeo' else 'de voz' end ||
         case when c.tipo = 'direta' then ' com você' else ' em #' || coalesce(nullif(c.nome, ''), 'canal') end || '. Entre pelas Conversas.', 500)
  from conversa_membros m where m.conversa = p_conversa and m.usuario <> v;
  perform interno.chat_aviso(p_conversa, 'chamada', null, case when r.video then 'video' else 'voz' end);
  perform interno.registrar('chamada_iniciada', r.id::text, jsonb_build_object('conversa', p_conversa, 'video', r.video));
  return interno.reuniao_json(r);
end $$;

/** As chamadas acontecendo agora nas conversas em que estou, com quem está em cada uma. */
create or replace function public.chat_chamadas() returns jsonb language plpgsql security definer set search_path = interno, pg_temp as $$
begin
  perform interno.eu();
  if not interno.voluntario() then return '[]'::jsonb; end if;
  perform interno.chamadas_limpar();
  return (select coalesce(jsonb_agg(interno.reuniao_json(r) order by r.iniciada_em desc), '[]'::jsonb)
          from reunioes r join conversa_membros m on m.conversa = r.conversa and m.usuario = auth.uid()
          where r.conversa is not null and r.status = 'ao_vivo');
end $$;

do $$
declare f record;
begin
  for f in select p.oid::regprocedure as assinatura from pg_proc p join pg_namespace n on n.oid = p.pronamespace
           where n.nspname = 'public' and p.proname in ('chat_chamada_iniciar', 'chat_chamadas') loop
    execute format('revoke all on function %s from public', f.assinatura);
    execute format('grant execute on function %s to authenticated, service_role', f.assinatura);
  end loop;
end $$;

-- ───────────────────────────── Rede Lúcia v2: fundação (Fase 2) ─────────────────────────────
-- Especificação aprovada em 30/10/2026 (docs/rede/ESPEC.md). Só acréscimos: nada da Rede de hoje muda de comportamento.
-- As telas novas ficam atrás do recurso "rede-v2" e usam estas tabelas; as funções públicas chegam na Fase 3.
-- Regra de quem vê o quê: interno.rede2_pode_ver, provada pela matriz em scripts/testar-rede.mjs.

alter table interno.perfis add column if not exists rede_handle text;
alter table interno.perfis add column if not exists rede_modo text not null default 'aberto';
alter table interno.perfis add column if not exists rede_fixado uuid;
alter table interno.perfis add column if not exists rede_18 boolean not null default false;
alter table interno.perfis add column if not exists rede_consentimento integer;
alter table interno.perfis add column if not exists rede_selos text[] not null default '{}';
do $$
begin
  alter table interno.perfis add constraint perfis_rede_handle_formato check (rede_handle is null or rede_handle ~ '^[a-z0-9_]{3,20}$');
exception when duplicate_object then null;
end $$;
do $$
begin
  alter table interno.perfis add constraint perfis_rede_modo check (rede_modo in ('aberto', 'trancado', 'invisivel'));
exception when duplicate_object then null;
end $$;
create unique index if not exists perfis_rede_handle on interno.perfis (rede_handle) where rede_handle is not null;

-- Posts: os tipos novos, a árvore de respostas e o público da v2. "publico" nulo = post da Rede de hoje (vale o alcance).
alter table interno.rede_posts add column if not exists tipo text not null default 'post';
alter table interno.rede_posts add column if not exists titulo text;
alter table interno.rede_posts add column if not exists corpo text;
alter table interno.rede_posts add column if not exists publico text;
alter table interno.rede_posts add column if not exists root_id uuid references interno.rede_posts (id) on delete cascade;
alter table interno.rede_posts add column if not exists profundidade smallint not null default 0;
alter table interno.rede_posts add column if not exists quote_of uuid references interno.rede_posts (id) on delete set null;
alter table interno.rede_posts add column if not exists flair text;
alter table interno.rede_posts add column if not exists nucleo uuid;
alter table interno.rede_posts add column if not exists aceita uuid;
alter table interno.rede_posts add column if not exists verificada boolean not null default false;
alter table interno.rede_posts add column if not exists travado boolean not null default false;
alter table interno.rede_posts add column if not exists fixado boolean not null default false;
alter table interno.rede_posts add column if not exists editado_em timestamptz;
alter table interno.rede_posts add column if not exists apagado_em timestamptz;
do $$
begin
  alter table interno.rede_posts add constraint rede_posts_tipo check (tipo in ('post', 'discussao', 'duvida', 'chamado', 'enquete', 'aviso'));
exception when duplicate_object then null;
end $$;
do $$
begin
  alter table interno.rede_posts add constraint rede_posts_publico check (publico is null or publico in ('internet', 'membros', 'seguidores', 'comunidade', 'nucleo', 'equipe'));
exception when duplicate_object then null;
end $$;
do $$
begin
  alter table interno.rede_posts add constraint rede_posts_tamanhos check (char_length(coalesce(titulo, '')) <= 140 and char_length(coalesce(corpo, '')) <= 10000 and char_length(coalesce(flair, '')) <= 40);
exception when duplicate_object then null;
end $$;
do $$
begin
  alter table interno.rede_posts add constraint rede_posts_nucleo_com_publico check (publico <> 'nucleo' or nucleo is not null);
exception when duplicate_object then null;
end $$;
do $$
begin
  alter table interno.rede_posts add column busca tsvector generated always as (
    to_tsvector('portuguese', coalesce(titulo, '') || ' ' || texto || ' ' || coalesce(corpo, ''))) stored;
exception when duplicate_column then null;
end $$;
create index if not exists rede_posts_raiz on interno.rede_posts (root_id, criado_em);
create index if not exists rede_posts_busca on interno.rede_posts using gin (busca);
create index if not exists rede_posts_nucleo on interno.rede_posts (nucleo, criado_em desc) where nucleo is not null;

/** Resposta herda a raiz e ganha um nível. A raiz vem do banco, nunca de quem envia. */
create or replace function interno.rede2_arvore() returns trigger language plpgsql security definer set search_path = interno, pg_temp as $$
declare v_pai rede_posts;
begin
  if new.resposta_a is null then
    new.root_id := null;
    new.profundidade := 0;
  else
    select * into v_pai from rede_posts where id = new.resposta_a;
    new.root_id := coalesce(v_pai.root_id, v_pai.id);
    new.profundidade := least(coalesce(v_pai.profundidade, 0) + 1, 32000);
  end if;
  return new;
end $$;
drop trigger if exists rede2_arvore on interno.rede_posts;
create trigger rede2_arvore before insert or update of resposta_a on interno.rede_posts for each row execute function interno.rede2_arvore();

create table if not exists interno.rede_post_edicoes (
  id uuid primary key default gen_random_uuid(),
  post uuid not null references interno.rede_posts (id) on delete cascade,
  texto_anterior text not null,
  criado_em timestamptz not null default now()
);
create index if not exists rede_post_edicoes_post on interno.rede_post_edicoes (post, criado_em);

create table if not exists interno.rede_midia (
  id uuid primary key default gen_random_uuid(),
  post uuid not null references interno.rede_posts (id) on delete cascade,
  caminho text not null unique check (caminho ~ '^[a-f0-9-]{36}/[a-f0-9-]{36}\.(jpg|png|webp)$'),
  tipo text not null check (tipo in ('image/jpeg', 'image/png', 'image/webp')),
  largura integer check (largura between 1 and 8000),
  altura integer check (altura between 1 and 8000),
  blurhash text check (char_length(coalesce(blurhash, '')) <= 100),
  alt text not null default '' check (char_length(alt) <= 1000),
  ordem smallint not null default 0 check (ordem between 0 and 3),
  criado_em timestamptz not null default now(),
  unique (post, ordem)
);

-- Uma reação por pessoa, tipo e post: o total é contado, nunca guardado num campo que dois pedidos disputam.
create table if not exists interno.rede_reacoes (
  post uuid not null references interno.rede_posts (id) on delete cascade,
  usuario uuid not null references interno.perfis (id) on delete cascade,
  tipo text not null check (tipo in ('apoio', 'util')),
  criado_em timestamptz not null default now(),
  primary key (post, usuario, tipo)
);

create table if not exists interno.rede_enquetes (
  post uuid primary key references interno.rede_posts (id) on delete cascade,
  prazo timestamptz not null,
  multipla boolean not null default false
);
create table if not exists interno.rede_opcoes (
  id uuid primary key default gen_random_uuid(),
  enquete uuid not null references interno.rede_enquetes (post) on delete cascade,
  texto text not null check (char_length(texto) between 1 and 80),
  ordem smallint not null check (ordem between 0 and 5),
  unique (enquete, ordem)
);
-- Voto secreto: a função de votar confere a pessoa, mas nenhuma função devolve quem votou em quê, só os totais.
create table if not exists interno.rede_votos (
  opcao uuid not null references interno.rede_opcoes (id) on delete cascade,
  usuario uuid not null references interno.perfis (id) on delete cascade,
  primary key (opcao, usuario)
);

create table if not exists interno.rede_chamados (
  post uuid primary key references interno.rede_posts (id) on delete cascade,
  inicio timestamptz not null,
  fim timestamptz,
  cidade text not null check (char_length(cidade) between 2 and 80),
  ponto text not null check (char_length(ponto) between 3 and 140),
  tipo text not null default 'ato' check (tipo in ('ato', 'assembleia', 'roda', 'mutirao', 'aula', 'outro')),
  link text check (link is null or link ~ '^https://'),
  cancelado boolean not null default false,
  check (fim is null or fim > inicio)
);

create table if not exists interno.rede_comunidades (
  slug text primary key check (slug ~ '^[a-z0-9-]{2,60}$'),
  nome text not null check (char_length(nome) between 3 and 60),
  descricao text not null default '' check (char_length(descricao) <= 500),
  categoria text not null check (categoria in ('lutas', 'disciplinas', 'instituto')),
  tipo text not null default 'aberta' check (tipo in ('aberta', 'restrita', 'fechada')),
  publico_padrao text not null default 'membros' check (publico_padrao in ('internet', 'membros', 'comunidade')),
  icone text not null default '' check (char_length(icone) <= 40),
  cor text not null default '' check (cor = '' or cor ~ '^#[0-9a-f]{6}$'),
  aulas text[] not null default '{}',
  trilhas text[] not null default '{}',
  apelidos text[] not null default '{}',
  criada_por uuid references interno.perfis (id) on delete set null,
  criada_em timestamptz not null default now(),
  -- Só as comunidades das disciplinas abrem para a internet (decisão 2).
  check (publico_padrao <> 'internet' or categoria = 'disciplinas')
);
create index if not exists rede_comunidades_apelidos on interno.rede_comunidades using gin (apelidos);

create table if not exists interno.rede_comunidade_membros (
  comunidade text not null references interno.rede_comunidades (slug) on delete cascade on update cascade,
  usuario uuid not null references interno.perfis (id) on delete cascade,
  papel text not null default 'membro' check (papel in ('membro', 'moderacao')),
  situacao text not null default 'ativo' check (situacao in ('ativo', 'pendente', 'banido')),
  banido_ate timestamptz,
  entrou_em timestamptz not null default now(),
  primary key (comunidade, usuario)
);
create index if not exists rede_comunidade_membros_usuario on interno.rede_comunidade_membros (usuario);

create table if not exists interno.rede_comunidade_regras (
  comunidade text not null references interno.rede_comunidades (slug) on delete cascade on update cascade,
  numero smallint not null check (numero between 1 and 20),
  titulo text not null check (char_length(titulo) between 3 and 80),
  texto text not null default '' check (char_length(texto) <= 500),
  primary key (comunidade, numero)
);
create table if not exists interno.rede_comunidade_flairs (
  comunidade text not null references interno.rede_comunidades (slug) on delete cascade on update cascade,
  nome text not null check (char_length(nome) between 2 and 40),
  cor text not null default '' check (cor = '' or cor ~ '^#[0-9a-f]{6}$'),
  primary key (comunidade, nome)
);
-- Comunidade nova só por proposta aprovada pela coordenação (decisão 4).
create table if not exists interno.rede_propostas (
  id uuid primary key default gen_random_uuid(),
  autor uuid references interno.perfis (id) on delete set null,
  slug text not null check (slug ~ '^[a-z0-9-]{2,60}$'),
  nome text not null check (char_length(nome) between 3 and 60),
  objetivo text not null check (char_length(objetivo) between 20 and 1000),
  regras text not null check (char_length(regras) between 20 and 2000),
  moderadores uuid[] not null check (cardinality(moderadores) >= 2),
  situacao text not null default 'aberta' check (situacao in ('aberta', 'aprovada', 'recusada')),
  decidida_por uuid references interno.perfis (id) on delete set null,
  motivo text not null default '' check (char_length(motivo) <= 500),
  criado_em timestamptz not null default now()
);

create table if not exists interno.rede_nucleos (
  id uuid primary key default gen_random_uuid(),
  nucleo uuid unique references interno.nucleos (id) on delete set null,
  nome text not null check (char_length(nome) between 3 and 80),
  cidade text not null default '' check (char_length(cidade) <= 80),
  trilha text check (trilha is null or trilha ~ '^[a-z0-9-]{2,80}$'),
  criado_por uuid references interno.perfis (id) on delete set null,
  criado_em timestamptz not null default now()
);
do $$
begin
  alter table interno.rede_posts add constraint rede_posts_nucleo_fk foreign key (nucleo) references interno.rede_nucleos (id) on delete cascade;
exception when duplicate_object then null;
end $$;
create table if not exists interno.rede_nucleo_membros (
  nucleo uuid not null references interno.rede_nucleos (id) on delete cascade,
  usuario uuid not null references interno.perfis (id) on delete cascade,
